insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('rg_mogaram_1', 'side', '연담·모가람', '식은 보리차', '객사 작은 방 창가. 굳은 손으로 찻주전자를 못 드는 모가람이 서른 해 모아 둔 요괴 쪽지를 불 끄던 물에 다 잃었다며, 「요괴 버릇 기록」을 새로 엮고 싶다고 한다. 보고서에는 이겼다·졌다만 있고 요괴가 어떻게 움직였는지는 없었다고. 싸워 본 사람만 볼 수 있으니 보고 와서 불러 달라는 주문이다. 받아 적을 손이 없어 조사원이 붓을 쥔다 — 첫 줄.', 'hq_dorm', 45, '{mdq_1}'::text[], null, 1660, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = null where quest_id = 'rg_mogaram_1';
delete from public.world_quest_steps where quest_id = 'rg_mogaram_1' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_mogaram_1', 1, '주전자 앞의 손', '주전자 앞의 손', '{"at": ["hq_dorm"]}'::jsonb, '[{"s": null, "t": "늦은 오후 해가 객사 작은 방 창호지를 누렇게 물들였다. 창가 탁자에는 찻주전자 하나와 빈 잔 둘이 놓여 있었다. 마당 감나무에서 까치가 깍깍 울었다."}, {"s": null, "t": "기록관 모가람이 탁자 앞에 앉아 찻주전자를 내려다보고 있었다. 굳은 두 손은 무릎 위에 가지런히 얹혀 있었다. 손가락 마디가 곧게 펴진 채 굽지 않았다."}, {"s": null, "t": "문턱에서 내 발소리가 나자 모가람이 고개를 들었다. 부스스한 갈색 머리 아래로 순한 눈꼬리가 처졌다."}, {"s": "night_office:mo", "t": "조사원님! 마침 잘 오셨어요. 같은 정통파 조사원이 찾아와 주니까 이 방이 다 환하네요.", "fac": "night_office", "spec": 1, "grp": 1}, {"s": "night_office:mo", "t": "조사원님! 마침 잘 오셨어요. 남의 세력 객사까지 일부러 와 주시고요. 앉으세요, 앉으세요.", "fac_not": "night_office", "spec": 2, "grp": 1}, {"s": null, "t": "모가람이 턱으로 찻주전자를 가리켰다. 웃는 얼굴인데 눈길은 제 손등에 가 있었다."}, {"s": "night_office:mo", "t": "보리차 한 잔 내 드리고 싶은데요. 서희가 아침에 채워 두고 갔어요. 저는 이걸 들 수가 없어서, 아침부터 들여다보기만 했어요."}, {"s": "night_office:mo", "t": "조사원님이 따라 주실래요? 두 잔이요. 한 잔은 조사원님 몫, 한 잔은… 제 입에 좀 대 주시고요."}, {"s": null, "t": "나는 주전자를 들어 두 잔에 보리차를 따랐다. 차는 다 식어 김 한 줄기 오르지 않았다. 잔 하나를 모가람의 입가에 대자, 모가람이 고개를 숙여 한 모금 마셨다."}, {"s": "night_office:mo", "t": "아, 맛있다. 뜨거운 차는 종이에 해롭거든요. 서른 해를 식혀 마셨더니 이제는 식은 게 제 맛이에요."}, {"s": null, "t": "모가람이 잔에서 입을 떼고 창밖을 보았다. 마당 너머 장서각 지붕이 그을음에 검게 얼룩져 있었다."}, {"s": "night_office:mo", "t": "조사원님, 저 서가에 불나던 밤에요. 제 방 책상 서랍에 쪽지 뭉치가 하나 있었어요. 서른 해 동안 조사원들 보고서를 정서하면서, 요괴 얘기만 따로 옮겨 적은 쪽지요."}, {"s": "night_office:mo", "t": "불 끄느라 다들 물을 퍼부었잖아요. 그 물이 제 방까지 흘러들었어요. 서랍을 열어 보니 먹이 다 풀려서 쪽지가 그냥 시커먼 떡이 돼 있더라고요."}, {"s": null, "t": "모가람은 웃으며 말했지만, 말끝에서 숨을 한 번 길게 내쉬었다. 굳은 손등이 무릎 위에서 조금 들썩였다."}, {"s": null, "t": "나는 쪽지에 무엇을 적어 두었느냐고 물었다. 모가람이 기다렸다는 듯 몸을 앞으로 당겨 앉았다."}, {"s": "night_office:mo", "t": "요괴 버릇이요. 보고서엔 늘 「이겼다」 「졌다」만 있어요. 어디서 몇 마리, 다친 사람 몇. 그런데 요괴가 덤비기 전에 무엇을 먼저 하는지, 맞으면 어느 쪽으로 물러나는지는 한 줄도 없어요."}, {"s": "night_office:mo", "t": "그걸 아는 사람은 싸워 본 사람뿐이에요. 저는 서가 앞에서 종이만 넘겼으니까 한 번도 못 봤고요. 그래서 이번엔 처음부터 다시 엮어 보고 싶어요. 「요괴 버릇 기록」이라고요."}, {"s": null, "t": "모가람이 고개를 기울여 나를 올려다보았다. 부탁하는 사람의 얼굴이 쑥스러운지 입꼬리가 자꾸 올라갔다."}, {"s": "night_office:mo", "t": "그러니까 주문이에요. 조사원님이 나가서 싸우면서 요괴를 눈여겨보고, 돌아와서 저한테 불러 주세요. 엮는 건 제가 할게요. 서가 순서 외우듯이 머리에 다 넣어 둘게요."}, {"s": "night_office:mo", "t": "첫 장은 먹비 숲 먹비 넋으로 해요. 묵적 봉쇄령 쪽 보고서에 제일 자주 나오던 이름인데, 쪽지가 다 번져서 제일 먼저 잃은 이름이기도 해요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_mogaram_1', 2, '불러 주는 사람', '먹비 넋을(를) 물리친다', '{"at": ["hq_dorm"], "tasks": [{"t": "win", "m": ["mk_forest_1"], "n": 6}]}'::jsonb, '[{"s": null, "t": "객사로 돌아오니 창밖에 저녁 어스름이 내려앉아 있었다. 모가람은 창가 자리 그대로 앉아 있었다. 탁자 위 두 잔에는 식은 보리차가 반쯤 남아 있었다."}, {"s": null, "t": "내 옷자락에서 먹비 냄새가 났는지 모가람이 코를 킁킁거렸다. 젖은 숯 같은 냄새였다."}, {"s": "night_office:mo", "t": "먹비 숲 냄새네요! 보고서 종이에서도 꼭 이 냄새가 났어요. 어땠어요? 처음부터 다 말해 주세요. 하나도 빼지 말고요."}, {"s": null, "t": "나는 먹비 넋이 빗소리가 굵어질 때 먼저 덤볐다고 했다. 빗줄기가 가늘어지면 나무 그늘 쪽으로 슬금슬금 물러났다는 말도 했다."}, {"s": null, "t": "모가람이 눈을 감고 입술을 달싹였다. 내가 한 말을 한 글자씩 다시 굴려 보는 얼굴이었다."}, {"s": "night_office:mo", "t": "빗소리가 굵어지면 먼저. 가늘어지면 그늘로. …조사원님, 그늘로 물러날 때 등을 보였어요, 얼굴을 보였어요?"}, {"s": null, "t": "나는 잠깐 그때를 떠올렸다. 먹비 넋은 물러날 때도 얼굴을 이쪽으로 둔 채 뒷걸음질 쳤다. 나는 그렇다고 했다."}, {"s": "night_office:mo", "t": "그럼 도망가는 게 아니네요. 숨을 고르는 거예요. 등을 안 보이는 놈은 다시 와요. 그건 서른 해 보고서에서 배운 거예요. 「물러난 놈이 다시 와서 다쳤다」는 줄이 그렇게 많았거든요."}, {"s": null, "t": "모가람의 목소리가 빨라졌다. 모가람은 신이 나서 탁자 쪽으로 손을 뻗었다. 탁자 끝에 굴러다니던 붓 한 자루를 손끝으로 집으려는 것이었다."}, {"s": null, "t": "곧게 편 손가락이 붓대를 감싸지 못했다. 붓이 데구루루 굴러 탁자 아래로 툭 떨어졌다."}, {"s": null, "t": "모가람이 떨어진 붓을 내려다보았다. 신이 나서 빨개졌던 얼굴에서 핏기가 천천히 가셨다."}, {"s": "night_office:mo", "t": "…아, 참. 또 잊었네요. 이야기가 재밌으면 손이 먼저 나가요. 서른 해 버릇이라서요."}, {"s": "night_office:mo", "t": "하하, 괜찮아요. 머리에 넣어 두면 돼요. 서가 순서도 다 외우는걸요. 먹비 넋 한 장쯤이야…."}, {"s": null, "t": "모가람은 웃으며 말을 돌렸지만, 바닥의 붓에서 눈을 떼지 못했다. 나는 붓을 주워 들고 내가 받아 적겠다고 했다."}, {"s": null, "t": "모가람이 눈을 동그랗게 떴다. 그러다 불나던 그 밤이 떠올랐는지 입가가 조금 풀렸다."}, {"s": "night_office:mo", "t": "그 밤에도 받아 적어 주셨죠. 죽 먹고 나서요. …그럼 또 부탁해도 될까요? 대신 종이가 없어요. 객사 종이는 다 물에 젖어서, 먹을 대면 번져요."}, {"s": "night_office:mo", "t": "정제 황지면 좋겠어요. 물을 덜 먹거든요. 기록은 한 번 번지면 다시 못 읽어요. 그건 이번에 제가 제일 잘 알게 됐네요."}]'::jsonb, '{"xp": 5760}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_mogaram_1', 3, '첫 줄', '정제 황지을(를) 만든다, 정제 황지을(를) 넘긴다', '{"at": ["hq_dorm"], "tasks": [{"t": "craft", "items": ["fine_paper"], "n": 2}], "give": {"fine_paper": 2}}'::jsonb, '[{"s": null, "t": "객사 방에 등잔을 켰다. 내가 정제 황지 두 장을 탁자에 펼치자 모가람이 고개를 쑥 내밀어 종이 냄새를 맡았다."}, {"s": "night_office:mo", "t": "좋은 종이네요. 잘 뜨셨어요. 결이 고르고, 손에 쥐면 바스락하고요. …아, 쥐어 보지는 못하지만요."}, {"s": null, "t": "나는 벼루에 먹을 갈았다. 먹 가는 소리가 사각사각 방 안에 퍼지자 모가람이 눈을 감았다. 묵은 먹의 단내가 등잔 기름 냄새에 섞여 들었다."}, {"s": "night_office:mo", "t": "이 소리, 오랜만이에요. 서른 해 동안 날마다 듣던 소리인데, 불난 뒤로는 처음이에요."}, {"s": null, "t": "나는 붓에 먹을 묻히고 모가람을 보았다. 모가람이 눈을 뜨고 종이 맨 위를 턱으로 가리켰다."}, {"s": "night_office:mo", "t": "첫 줄은 이름이에요. 「먹비 넋」. 이름부터 써야 그다음 버릇이 그 요괴 것이 돼요."}, {"s": null, "t": "나는 「먹비 넋」이라고 썼다. 모가람이 그 세 글자를 오래 들여다보았다."}, {"s": "night_office:mo", "t": "그다음이요. 「빗소리가 굵어지면 먼저 덤빈다. 가늘어지면 그늘로 물러나되, 얼굴을 돌리지 않는다. 물러난 넋은 다시 온다.」"}, {"s": null, "t": "모가람이 한 마디씩 끊어 불렀다. 내 붓이 따라잡을 때까지 기다렸다가 다음 마디를 불렀다. 붓끝이 종이에 닿을 때마다 모가람의 어깨가 조금씩 따라 움직였다."}, {"s": "night_office:mo", "t": "끝에 하나만 더요. 「본 사람, 이 줄을 적은 조사원.」 누가 봤는지가 있어야 기록이에요. 남의 말을 옮긴 건 소문이고요."}, {"s": null, "t": "나는 그 줄을 적고 붓을 내려놓았다. 모가람이 다 마른 먹 위로 굳은 손등을 가만히 갖다 댔다. 종이를 쓰다듬는 대신이었다."}, {"s": "night_office:mo", "t": "됐어요. 첫 장이에요. 서른 해 만에 제가 엮은 첫 장이요. 손은 조사원님 거지만요."}, {"s": null, "t": "모가람이 남은 보리차 잔을 턱으로 가리켰다. 나는 잔을 들어 모가람의 입에 대 주었다. 모가람이 한 모금 마시고 웃었다."}, {"s": "night_office:mo", "t": "조사원님, 이 기록 한 장으로 끝내기엔 아까워요. 요괴 갈래가 열셋이고, 갈래마다 버릇이 다 달라요. 앞으로도 싸우다 눈여겨본 게 있으면 불러 주실래요?"}, {"s": "night_office:mo", "t": "오늘은 몇 번이나 요괴를 눈여겨봤는지, 그런 것도 세어 와 주세요. 요괴 몸에서 떨어진 것도 좋고요. 비늘이든 재든, 버릇은 몸에도 남거든요."}, {"s": null, "t": "나는 그러겠다고 했다. 모가람이 남은 정제 황지 한 장을 창가 쪽으로 밀어 달라고 했다. 내가 종이를 밀어 놓자 모가람이 그 위로 고개를 숙였다."}, {"s": "night_office:mo", "t": "이 장은 비워 두세요. 다음에 오실 때 쓸 자리예요. 보리차도 식혀 둘게요. …아니, 서희한테 식혀 두라고 할게요."}]'::jsonb, '{"xp": 5760, "gil": 185, "items": {"moonlight_essence": 2, "travel_ration": 2}}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('rg_mogaram_2', 'side', '연담·모가람', '틀린 이름', '조사원이 불러 준 요괴 이름 하나가 틀렸다. 잿빛 들녘에서 빗속에 떠다니던 것을 「촛농 도깨비불」이라 불렀는데, 모가람은 그 버릇이 「비묻은 도깨비불」 것이라 한다. 「틀린 이름으로 적으면 그 기록을 읽고 나간 사람이 엉뚱한 버릇을 믿고 싸워요.」 둘은 객사 뒤로 이어진 잿빛 들녘과 폐쇄 사당에 두 도깨비불을 견주어 보러 간다. 모가람은 손이 굳은 뒤 처음으로 객사 문밖에 나선다.', 'hq_dorm', 45, '{rg_mogaram_1}'::text[], null, 1661, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = '{"regular": "mogaram", "stage": 2}'::jsonb where quest_id = 'rg_mogaram_2';
delete from public.world_quest_steps where quest_id = 'rg_mogaram_2' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_mogaram_2', 1, '줄 하나에 친 먹', '줄 하나에 친 먹', '{"at": ["hq_dorm"]}'::jsonb, '[{"s": null, "t": "아침 비가 그친 객사 마당에 물웅덩이가 반짝였다. 처마 끝에서 빗물이 똑, 똑 떨어졌다. 창가 탁자에 보리차 잔 둘이 놓여 있었고, 모가람은 그 옆에 펼쳐 둔 기록을 내려다보고 있었다."}, {"s": null, "t": "기록은 어느새 손가락 한 마디 두께로 쌓여 있었다. 모가람은 나를 보자마자 턱으로 그 더미를 가리켰다."}, {"s": "night_office:mo", "t": "조사원님, 이것 좀 보세요. 그사이 불러 주신 게 벌써 스무 장이 넘어요. 가져다주신 것도 창턱에 다 늘어놨어요. 원령재 한 줌, 수귀 비늘 셋, 요기 결정 두 알. 하나하나 냄새가 달라요."}, {"s": "night_office:mo", "t": "수귀 비늘은 비린내 뒤에 쇠 냄새가 나요. 그래서 수귀가 쇳소리 나는 데로 꼬이나 봐요. 그것도 적어 두셨죠?"}, {"s": null, "t": "나는 적어 두었다고 했다. 모가람이 흐뭇하게 웃다가, 기록 한 장 위에서 눈길을 멈췄다. 웃음이 조금 오그라들었다."}, {"s": "night_office:mo", "t": "그런데요, 이 장이요. 지난번에 잿빛 들녘에서 보셨다는 거요. 「촛농 도깨비불. 비가 오면 불빛이 커지고, 젖은 이삭 위로만 떠다닌다.」"}, {"s": "night_office:mo", "t": "촛농 도깨비불은 비를 싫어해요. 이름처럼 촛농이 녹아서 생긴 놈이라, 젖으면 불이 꺼지거든요. 폐쇄 사당 처마 밑에만 붙어 있다고 보고서마다 적혀 있었어요."}, {"s": null, "t": "모가람이 기록 쪽으로 고개를 숙였다. 굳은 손등으로 그 줄 위를 톡톡 두드렸다."}, {"s": "night_office:mo", "t": "비가 오면 커지는 건 비묻은 도깨비불이에요. 이름이 둘 다 「도깨비불」로 끝나니까 헷갈리셨나 봐요."}, {"s": null, "t": "귀 끝이 화끈해졌다. 나는 줄을 긋고 고쳐 쓰겠다고 했다. 모가람이 고개를 저었다."}, {"s": "night_office:mo", "t": "긋고 고치는 건 쉬워요. 그런데 이건 조사원님이 보신 거잖아요. 제가 보고서만 믿고 고쳤다가, 실은 조사원님 눈이 맞았으면요? 그럼 서른 해 묵은 보고서가 틀린 거예요."}, {"s": "night_office:mo", "t": "틀린 이름으로 적으면, 이 기록을 읽고 나간 사람이 엉뚱한 버릇을 믿고 싸워요. 비 오는 날 사당에 갔다가 불이 안 꺼지는 놈을 만나면 어떡해요. 그래서 이름은 틀리면 안 돼요."}, {"s": null, "t": "모가람이 창밖 객사 뒤쪽을 보았다. 담 너머로 잿빛 들녘의 누런 이삭이 바람에 일렁였다."}, {"s": "night_office:mo", "t": "그러니까 다시 보러 가요. 저도 같이요. 들녘은 객사 뒷문만 나서면 바로잖아요. 걷는 건 손이 없어도 되니까요."}, {"s": null, "t": "나는 놀라서 모가람을 보았다. 손이 굳은 뒤로 모가람이 객사 문밖에 나섰다는 말은 들어 본 적이 없었다."}, {"s": "night_office:mo", "t": "하하, 그렇게 보지 마세요. 저도 한 번은 제 눈으로 보고 싶어요. 서른 해 동안 「도깨비불」을 오백 번은 정서했을 텐데, 진짜 불은 한 번도 못 봤거든요."}, {"s": "night_office:mo", "t": "조사원님이 싸우시면 저는 들녘 가에서 볼게요. 비가 갓 그쳤으니까 비묻은 놈이 나와 있을 거예요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_mogaram_2', 2, '들녘 가의 기록관', '잿빛 들녘에 간다, 비묻은 도깨비불을(를) 물리친다', '{"at": ["field_outskirts"], "tasks": [{"t": "travel", "r": ["field_outskirts"], "n": 1}, {"t": "win", "m": ["m_outskirts_1"], "n": 4}]}'::jsonb, '[{"s": null, "t": "잿빛 들녘 둑길에 모가람이 서 있었다. 축축한 흙냄새와 젖은 볏짚 냄새가 바람에 실려 왔다. 모가람의 바짓단은 진흙이 튀어 얼룩덜룩했다."}, {"s": null, "t": "내가 마지막 도깨비불을 흩어 버리고 돌아오자, 모가람이 둑길에서 발을 동동 굴렀다."}, {"s": "night_office:mo", "t": "봤어요, 봤어요! 진짜로 이삭 위로만 떠다니네요! 마른 길 쪽으로는 한 번도 안 내려왔어요. 조사원님이 길 쪽으로 몰아도 휙 돌아서 이삭 위로 갔잖아요!"}, {"s": null, "t": "모가람의 목소리가 들녘 끝까지 쩌렁쩌렁 울렸다. 이삭 사이에 숨어 있던 허수 까마귀 몇 마리가 푸드덕 날아올랐다."}, {"s": "night_office:mo", "t": "아, 쉿, 쉿. 제가 너무 떠들었네요. 서고에선 늘 조용히 하라고 신입들을 다그쳤는데요."}, {"s": null, "t": "나는 웃음이 나와 고개를 돌렸다. 모가람이 진흙 묻은 바짓단을 내려다보고 저도 따라 웃었다."}, {"s": null, "t": "모가람의 뺨에 진흙 한 점이 튀어 있었다. 손으로 닦을 수 없는 모가람이 어깨에 뺨을 문지르려다 더 번지게 했다. 나는 소매 끝으로 그 자리를 닦아 주었다."}, {"s": "night_office:mo", "t": "아, 고마워요. 손이 없으니까 얼굴에 뭐가 묻어도 모르고 다녀요. 객사에 돌아가서 서희 보기 전에 닦았으니 다행이에요."}, {"s": "night_office:mo", "t": "그런데요, 보세요. 조사원님이 보신 게 맞았어요. 비 오면 커지고, 젖은 이삭 위로만. 틀린 건 이름 하나였어요. 눈은 맞고요."}, {"s": "night_office:mo", "t": "그러니까 반만 고치면 돼요. 버릇은 그대로 두고 이름만 「비묻은 도깨비불」로요."}, {"s": null, "t": "모가람이 들녘 끝 언덕 위를 보았다. 무너진 담장 너머로 폐쇄 사당의 기와지붕이 비죽 솟아 있었다."}, {"s": null, "t": "나는 다리가 아프지 않으냐고 물었다. 모가람이 둑길 끝까지 걸어온 제 발을 내려다보았다."}, {"s": "night_office:mo", "t": "조금요. 서고에선 하루 종일 서 있어도 괜찮았는데, 흙길은 다르네요. 그래도 이대로 돌아가면 반쪽짜리 나들이예요."}, {"s": "night_office:mo", "t": "하나 남았어요. 촛농 도깨비불이요. 그놈이 정말 비를 싫어하는지, 보고서 말이 맞는지는 아직 몰라요. 오늘 둘 다 보면 이 장은 다시는 안 고쳐도 돼요."}, {"s": "night_office:mo", "t": "사당 처마 밑을 살펴봐 주세요. 촛농 떨어진 자국이 있으면 거기가 그놈 자리예요. 비 그친 날 처마 밑에만 자국이 몰려 있으면, 보고서가 맞은 거고요."}]'::jsonb, '{"xp": 5760}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_mogaram_2', 3, '고쳐 쓴 이름', '폐쇄 사당을(를) 살핀다', '{"at": ["shrine_ruins"], "tasks": [{"t": "search", "r": ["shrine_ruins"], "n": 2}]}'::jsonb, '[{"s": null, "t": "폐쇄 사당 처마 밑 마루에 허연 촛농 자국이 점점이 굳어 있었다. 처마 바깥 젖은 돌바닥에는 한 점도 없었다. 나는 모가람을 불러 그 자리를 보여 주었다."}, {"s": null, "t": "모가람이 처마 밑으로 고개를 들이밀고 마루를 내려다보았다. 쭈그려 앉으려다 손을 짚을 수 없어 휘청했다. 나는 얼른 모가람의 팔꿈치를 받쳤다."}, {"s": "night_office:mo", "t": "아이고, 고마워요. 손을 못 짚으니까 앉는 것도 일이네요. …보세요, 처마 안쪽에만 있어요. 보고서가 맞았어요. 둘 다 맞았어요."}, {"s": null, "t": "모가람이 마루에 엉덩이를 붙이고 앉아 숨을 골랐다. 사당 뒤 대숲에서 바람이 사르르 불어와 젖은 댓잎 냄새를 실어 왔다."}, {"s": "night_office:mo", "t": "조사원님, 붓 가져오셨어요? 여기서 고쳐요. 본 자리에서 고치는 게 제일 정확하거든요."}, {"s": null, "t": "나는 품에서 붓과 기록 한 장을 꺼냈다. 「촛농」 두 글자 위에 줄을 긋고, 그 옆에 「비묻은」 석 자를 고쳐 썼다. 버릇 줄은 한 글자도 건드리지 않았다."}, {"s": "night_office:mo", "t": "그은 줄은 지우지 마세요. 틀렸던 것도 남겨 둬야, 다음 사람이 「이 둘을 헷갈렸구나」 하고 알아요. 그것도 버릇이에요. 사람 버릇이요."}, {"s": null, "t": "모가람이 고친 글자를 내려다보다가 큭큭 웃었다. 웃음이 그치지 않아 어깨가 들썩였다."}, {"s": "night_office:mo", "t": "서른 해 동안 남의 보고서에서 틀린 이름을 수백 개는 찾아냈어요. 제가 찾은 걸 신입들이 고치러 다녔고요. 이번엔 제가 고치러 나왔네요. 기록관 체면이 말이 아니에요."}, {"s": null, "t": "나는 바짓단의 진흙이 기록관 체면을 더 깎는다고 했다. 모가람이 제 바짓단을 내려다보고 소리 내어 웃었다."}, {"s": "night_office:mo", "t": "이건 일한 자국이에요. 서희한테 빨아 달라고 하면 또 혼나겠지만요."}, {"s": null, "t": "해가 사당 지붕 너머로 기울었다. 우리는 둑길을 따라 객사 쪽으로 걸었다. 모가람은 걸으면서도 들녘 이삭 위를 자꾸 돌아보았다."}, {"s": "night_office:mo", "t": "조사원님, 오늘 처음으로 제가 적는 것을 제 눈으로 봤어요. 불러 주시는 말만 듣고 엮을 때보다 훨씬 또렷해요."}, {"s": "night_office:mo", "t": "…그래도 매번 따라 나가진 못하겠어요. 들녘까지가 제 다리 끝이에요. 그 너머는 계속 조사원님 눈으로 볼게요."}, {"s": null, "t": "객사 뒷문 앞에서 모가람이 걸음을 멈추고 나를 돌아보았다. 노을빛에 그을린 장서각 지붕이 붉게 물들어 있었다."}, {"s": "night_office:mo", "t": "이름은 제가 지킬게요. 조사원님은 보기만 하세요. 틀리면 또 같이 고치러 나오면 되니까요."}]'::jsonb, '{"xp": 5760, "gil": 185, "items": {"moonlight_essence": 2, "travel_ration": 2}}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('rg_mogaram_3', 'side', '연담·모가람', '받아쓰기 연습', '모가람이 조사원의 비뚤배뚤한 글씨를 보고 웃다가, 서른 해 전 처음 서가에 들어왔을 때 제 글씨도 그랬다고 처음 이야기한다. 비뚤어서 정서를 못 맡고, 밤마다 혼자 서가 이름표를 베껴 쓰며 손을 길렀다고. 조사원은 이야기 사이사이 목이 마른 모가람에게 묻지 않고 찻잔을 입에 대 준다.', 'hq_dorm', 45, '{rg_mogaram_2}'::text[], null, 1662, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = '{"regular": "mogaram", "stage": 3}'::jsonb where quest_id = 'rg_mogaram_3';
delete from public.world_quest_steps where quest_id = 'rg_mogaram_3' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_mogaram_3', 1, '비뚤배뚤한 기록', '비뚤배뚤한 기록', '{"at": ["hq_dorm"]}'::jsonb, '[{"s": null, "t": "저녁 장지문 너머로 객사 부엌의 밥 짓는 냄새가 흘러들었다. 창가 탁자에는 기록이 두 무더기로 나뉘어 놓여 있었다. 모가람은 그중 한 무더기 앞에서 입을 가리지도 못하고 웃음을 참고 있었다."}, {"s": "night_office:mo", "t": "조사원님, 오셨어요? 그사이 가져다주신 거 잘 받았어요. 결계 파편이 셋이나 있던데요. 결계 깨는 요괴를 그렇게 많이 잡으셨어요? 그것도 다 적었어요. 아니, 조사원님이 적으셨죠."}, {"s": null, "t": "모가람이 두 무더기를 턱으로 번갈아 가리켰다. 왼쪽 무더기는 글씨가 곧았고, 오른쪽은 줄이 비탈길처럼 오른쪽 아래로 흘러내렸다."}, {"s": "night_office:mo", "t": "이쪽이 첫날 쓰신 거고, 이쪽이 요 며칠 쓰신 거예요. 요즘 것은요, 줄이 자꾸 내려가요. 싸우고 와서 바로 쓰시니까 팔이 지쳐서 그런가 봐요."}, {"s": "night_office:mo", "t": "여기 「먹물 두꺼비」는 「먹물 두껍이」가 됐고요. 하하, 죄송해요. 웃으면 안 되는데."}, {"s": null, "t": "모가람이 웃음을 참느라 입술을 꾹 다물었다. 손으로 입을 가릴 수 없어 고개를 창 쪽으로 홱 돌렸지만, 어깨가 들썩이는 것까지는 숨기지 못했다."}, {"s": null, "t": "나는 먹물 두꺼비와 싸우고 와서 바로 쓰느라 팔이 덜덜 떨렸다고 했다. 두꺼비가 먹물을 뿜어 눈앞이 캄캄했다는 말도 했다."}, {"s": "night_office:mo", "t": "아이고, 그러니까 「두껍이」가 됐구나. 두꺼비가 먹물로 조사원님 글씨까지 망쳐 놨네요. …알았어요, 알았어요. 이제 안 웃을게요."}, {"s": null, "t": "나는 낯이 뜨거워져서 오른쪽 무더기를 덮으려 했다. 모가람이 굳은 손등으로 내 손등을 툭 막았다."}, {"s": "night_office:mo", "t": "덮지 마세요. 흉보는 게 아니에요. 이 글씨에는 그날 얼마나 싸우셨는지가 다 남아 있어요. 기록관은 그런 것도 읽어요."}, {"s": null, "t": "모가람은 그렇게 말하고 오른쪽 무더기를 오래 내려다보았다. 웃음기가 가신 얼굴에 무언가를 떠올리는 기색이 비쳤다."}, {"s": null, "t": "나는 무엇을 떠올리느냐고 물었다. 모가람이 고개를 저으며 웃음으로 말을 돌렸다."}, {"s": "night_office:mo", "t": "아무것도 아니에요. 옛날 생각이요. 이따 연습하면서 말씀드릴게요."}, {"s": "night_office:mo", "t": "…오늘은 하나만 더 적고, 그다음엔 연습해요. 받아쓰기 연습이요. 서고 신입들한테 시키던 걸로요."}, {"s": "night_office:mo", "t": "적을 건 아홉 칸 뜰 칸 지키는 돌거북이에요. 보고서에 「느리다」 한 줄뿐이었어요. 그런 놈이 왜 아홉 칸 뜰 같은 데서 오래 살아남았는지, 느린 놈한테도 버릇이 있을 거예요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_mogaram_3', 2, '신입의 이름표', '칸 지키는 돌거북을(를) 물리친다', '{"at": ["hq_dorm"], "tasks": [{"t": "win", "m": ["mk_court_1"], "n": 5}]}'::jsonb, '[{"s": null, "t": "객사로 돌아오니 밤이 깊어 있었다. 등잔불 아래 모가람이 연습용 황지를 펼쳐 두고 기다리고 있었다. 황지 위에는 먹을 갈아 둔 벼루가 놓여 있었다."}, {"s": null, "t": "나는 돌거북이 칸 한가운데서는 머리를 집어넣고, 칸 금을 밟으면 머리를 내밀어 물었다고 했다. 칸 밖으로는 한 발짝도 나가지 않았다는 말도 했다."}, {"s": "night_office:mo", "t": "칸 금이요? 그럼 느린 게 아니라 기다리는 거네요. 자기 칸에 누가 발을 들일 때까지요. …좋아요, 받아 적으세요. 천천히요. 오늘은 줄이 내려가면 안 돼요."}, {"s": null, "t": "모가람이 한 마디씩 불렀다. 나는 줄이 내려가지 않게 붓을 쥔 손목에 힘을 주었다. 붓끝이 바르르 떨렸다."}, {"s": "night_office:mo", "t": "손목에 힘 빼세요. 힘을 주면 더 떨려요. 팔꿈치를 탁자에 붙이고, 붓만 세우세요. …그렇죠. 그거예요."}, {"s": null, "t": "나는 모가람이 일러 준 대로 팔꿈치를 붙였다. 줄이 조금 곧아졌다. 모가람이 고개를 끄덕이며 말끝을 흐렸다."}, {"s": "night_office:mo", "t": "저도 똑같은 소리를 들었어요. 서른 해 전에요. 「손목에 힘 빼라, 모가람.」"}, {"s": null, "t": "나는 붓을 멈추고 모가람을 보았다. 모가람은 창밖 어둠 쪽으로 눈을 돌렸다. 등잔불이 모가람의 옆얼굴에서 가물가물 흔들렸다."}, {"s": "night_office:mo", "t": "저 처음 서가에 들어왔을 때요, 글씨가 엉망이었어요. 조사원님 요즘 글씨보다 더요. 그래서 정서를 못 맡았어요. 일 년 내내 먼지만 털었어요."}, {"s": "night_office:mo", "t": "밤마다 혼자 남아서 서가 이름표를 베껴 썼어요. 「동쪽 첫째 서가」, 「동쪽 둘째 서가」. 그러다 보니 서가 순서를 다 외우게 됐고요. 다들 기록관이 머리가 좋아서 외운다고 하는데, 실은 글씨가 나빠서 외운 거예요."}, {"s": null, "t": "모가람의 목소리가 조금 잠겼다. 길게 말하느라 입술이 말라 있었다. 나는 붓을 내려놓고 잔을 찾았지만, 탁자 위 잔 둘은 비어 있었다."}, {"s": "night_office:mo", "t": "아, 보리차가 떨어졌네요. 서희가 오늘은 바빠서 못 들렀나 봐요. 괜찮아요, 괜찮아요. 말은 목으로 하는 거니까요."}, {"s": null, "t": "모가람은 괜찮다고 했지만 마른 입술을 자꾸 혀로 축였다. 나는 차를 끓여 오겠다고 했다. 모가람이 눈을 동그랗게 떴다가 이내 웃었다."}, {"s": "night_office:mo", "t": "그럼 영초 차로 해 주세요. 머리가 맑아져서 받아쓰기에 좋아요. 대신 꼭 식혀서요. 뜨거운 건 종이에도 저한테도 해로워요."}]'::jsonb, '{"xp": 5760}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_mogaram_3', 3, '묻지 않고 대 준 잔', '영초 차을(를) 만든다, 영초 차을(를) 넘긴다', '{"at": ["hq_dorm"], "tasks": [{"t": "craft", "items": ["spirit_tea"], "n": 2}], "give": {"spirit_tea": 2}}'::jsonb, '[{"s": null, "t": "나는 영초 차 두 잔을 창턱에 올려 밤바람에 식혔다. 잔을 손바닥으로 쥐어 보니 미지근했다. 그제야 잔 하나를 탁자에 내려놓았다."}, {"s": null, "t": "그때 장지문 밖에서 발소리가 나더니 서기관 연서희가 문틈으로 고개를 들이밀었다. 연서희는 주전자를 들고 있다가 탁자 위 잔을 보고 걸음을 멈췄다."}, {"s": "q:m_yeon", "t": "아, 벌써 차가 있네요. 늦어서 미안해요. 서당 애들한테 붙잡혀 있다 왔어요. …{이름} 님이 계시면 됐어요. 주전자는 두고 갈게요."}, {"s": null, "t": "연서희가 주전자를 문간에 내려놓고 조용히 문을 닫았다. 모가람이 닫힌 문을 보며 소리 없이 웃었다."}, {"s": "night_office:mo", "t": "서희는 늘 저래요. 남 챙기느라 자기 저녁은 걸러요. …자, 마저 해요. 신입 때 얘기 하다 말았네요."}, {"s": null, "t": "모가람이 창밖을 한 번 보고 다시 말을 이었다. 목소리가 아까보다 느렸다."}, {"s": "night_office:mo", "t": "일 년 만에 처음 정서를 맡던 날이요. 손이 떨려서 첫 글자에 먹을 뚝 떨어뜨렸어요. 버리려고 구겼는데, 선배 기록관님이 그걸 도로 펴서 서가 맨 끝에 꽂아 두셨어요."}, {"s": null, "t": "모가람이 잠깐 말을 쉬고 침을 꿀꺽 삼켰다. 나는 묻지 않고 잔을 들어 모가람의 입에 댔다. 모가람이 놀란 눈으로 나를 보다가 차를 한 모금 마셨다."}, {"s": "night_office:mo", "t": "…어떻게 아셨어요? 지금 딱 마시고 싶었는데."}, {"s": null, "t": "나는 모가람이 길게 말하고 나면 늘 침을 삼킨다고 했다. 모가람이 잔에서 입을 떼고 한참 나를 보았다."}, {"s": "night_office:mo", "t": "기록관 버릇을 다 읽으셨네요. 요괴 버릇 보러 다니시더니 사람 버릇도 보게 되셨나 봐요."}, {"s": "night_office:mo", "t": "그 선배님이 그러셨어요. 「먹 떨어뜨린 장도 기록이다. 네가 처음 쓴 날이니까.」 그 장, 서른 해 동안 서가 맨 끝에 있었어요. …불난 밤에 같이 탔겠죠."}, {"s": null, "t": "모가람이 창밖 장서각 쪽을 보았다. 어둠 속에서 그을린 지붕은 보이지 않았다. 나는 탁자 위 기록 맨 끝에 오늘 쓴 장을 끼워 넣었다. 줄이 아직 조금 내려가 있는 장이었다."}, {"s": null, "t": "모가람이 그 장을 내려다보고 고개를 끄덕였다. 굳은 손등으로 그 장 귀퉁이를 꾹 눌러 반듯하게 폈다."}, {"s": "night_office:mo", "t": "이 장은 버리지 마세요. 조사원님이 받아쓰기를 처음 배운 날이니까요. 맨 끝에 두세요. 그 선배님 자리에요."}, {"s": null, "t": "나는 남은 차를 다시 모가람의 입에 대 주었다. 이번에는 모가람이 망설이지 않고 받아 마셨다."}, {"s": "night_office:mo", "t": "다음엔 줄이 안 내려갈 거예요. 팔꿈치만 기억하세요. 저는 서른 해 걸렸는데, 조사원님은 훨씬 빠를 것 같아요."}]'::jsonb, '{"xp": 5760, "gil": 185, "items": {"moonlight_essence": 2, "travel_ration": 2}}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('rg_mogaram_4', 'side', '연담·모가람', '빈 칸', '기록에 끝내 못 채운 칸이 하나 있다. 장서각 지하서고 깊은 서가 사이에만 나온다는 「서가 그림자」 — 서른 해 서고를 지킨 모가람도 한 번도 본 적 없는 요괴다. 「비었다고 적어요. 빈 것도 기록이에요.」 그렇게 말하던 모가람이, 이번만은 제 눈으로 채우고 싶다고 한다. 둘은 밤에 등을 들고 불난 뒤 처음으로 서고 계단을 내려간다. 손을 못 쓰는 모가람은 목에 등을 걸고 조사원의 등 뒤를 밝힌다.', 'hq_dorm', 45, '{rg_mogaram_3}'::text[], null, 1663, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
