update public.world_quests set open_req = null where quest_id = 'rg_kangducheol_1';
delete from public.world_quest_steps where quest_id = 'rg_kangducheol_1' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_kangducheol_1', 1, '눈 감는 수련생들', '눈 감는 수련생들', '{"at": ["iron_monastery"]}'::jsonb, '[{"s": null, "t": "철벽 고찰 앞마당에 밤새 내린 눈이 무릎까지 쌓여 있었다. 처마 끝 고드름에서 물방울이 똑똑 떨어졌고, 법당 쪽에서 아침 범종 소리가 웅웅 울려 퍼졌다."}, {"s": null, "t": "마당 한가운데 눈을 쓸어 낸 자리에 수련생 여남은이 목검을 들고 두 줄로 마주 서 있었다. 아이들의 입김이 하얗게 피어올랐다."}, {"s": null, "t": "줄 사이를 털 두른 겉옷 차림의 덩치 큰 사람이 오가며 목청을 높였다. 헝클어진 머리를 푸른 끈으로 묶은 팔괘 연무청 교관 강두철이었다."}, {"s": "night_office:kang", "t": "막아라! 눈 감지 말고! 목검이 오는 걸 봐야 막을 거 아니냐!"}, {"s": null, "t": "맞은편 목검이 내려오자 앞줄 수련생 하나가 질끈 눈을 감고 고개를 돌렸다. 목검이 어깨에 퍽 떨어졌고, 수련생이 눈밭에 털썩 주저앉았다."}, {"s": null, "t": "강두철이 누구보다 먼저 달려갔다. 주저앉은 수련생을 덥석 들쳐 업고 처마 밑 평상까지 성큼성큼 걸어갔다."}, {"s": "night_office:kang", "t": "괜찮다, 괜찮아. 어깨는 붙어 있다! 잠깐 앉아서 숨 돌려라."}, {"s": null, "t": "수련생을 평상에 내려놓고 돌아서던 강두철이 마당 어귀에 선 나를 보았다. 눈이 휘둥그레지더니 이내 입이 크게 벌어졌다."}, {"s": "night_office:kang", "t": "하하! 너 그 신참이로구나! 연무장에서 스승님 목인장을 눕힌 {등급}! 이 산꼭대기까지 웬일이냐?", "fac": "night_office", "rank": [1, 4], "spec": 0, "grp": 1}, {"s": "night_office:kang", "t": "하하! 그 신참이 이제 판관 나리가 되셨소? 연무장에서 스승님 목인장을 눕힌 분이 이 산꼭대기까지 웬일이오? 아니, 수련장에선 내가 교관이니 말 좀 놓겠소!", "fac": "night_office", "rank": [5, 5], "spec": 0, "grp": 1}, {"s": "night_office:kang", "t": "하하! 너 그 신참이로구나! 연무장에서 스승님 목인장을 눕힌 조사원! 남의 수련장까지 웬일이냐?", "fac_not": "night_office", "spec": 2, "grp": 1}, {"s": null, "t": "나는 범종 소리를 따라 올라왔다가 목검 소리를 들었다고 했다. 연무청 교관이 왜 북쪽 고찰에 와 있느냐고도 물었다."}, {"s": "night_office:kang", "t": "여기가 내 옛 산문이다. 정청으로 내려가기 전에 이 고찰 뒤 산문에서 수련했거든. 겨울마다 애들을 데리고 올라온다. 막는 걸 배우려면 북쪽 바람부터 맞아 봐야 하니까!"}, {"s": null, "t": "강두철이 평상의 수련생을 턱으로 가리켰다. 수련생은 어깨를 문지르며 고개를 푹 숙이고 있었다."}, {"s": "night_office:kang", "t": "그런데 저놈들이 막을 줄을 몰라. 목검이 오면 눈부터 감는다. 때리는 건 사흘이면 배운다! 맞는 법은 평생이다!"}, {"s": "night_office:kang", "t": "그래서 말인데, 너 방패 노릇 좀 해 줘라. 애들이 너를 치고, 너는 막는다. 애들은 막는 걸 눈으로 보고 배운다."}, {"s": null, "t": "나는 막는 법을 제대로 배운 적이 없다고 했다. 강두철이 두툼한 손바닥으로 내 어깨를 툭툭 쳤다."}, {"s": "night_office:kang", "t": "그러니까 먼저 맞아 보고 와라! 막는 법은 맞아 봐야 안다. 목검에 맞는 거랑 요괴한테 맞는 건 달라. 요괴는 봐주지 않거든."}, {"s": "night_office:kang", "t": "설피골에 내려가서 요괴 몇 놈이랑 붙어 봐라. 어디를 맞았는지, 어디는 막았는지 잘 기억해 와. 그게 애들 앞에 설 밑천이다."}, {"s": null, "t": "강두철이 평상 쪽을 돌아보았다. 수련생 소매 끝에서 해진 누비가 삐죽 비어져 나와 있었다."}, {"s": "night_office:kang", "t": "오는 길에 하나만 더. 애들 팔 덮개가 다 해졌다. 설피골 요수 가죽을 질기게 손질해서 두 장만 만들어 와라. 맞을 때 팔을 받쳐 줄 거다."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_kangducheol_1', 2, '맞은 데가 배운 데', '설피골의 요괴를 물리친다, 강화 요수 가죽을(를) 만든다, 강화 요수 가죽을(를) 넘긴다', '{"at": ["iron_monastery"], "tasks": [{"t": "win", "r": ["snow_hollow"], "n": 5}, {"t": "craft", "items": ["reinforced_leather"], "n": 2}], "give": {"reinforced_leather": 2}}'::jsonb, '[{"s": null, "t": "설피골에서 돌아오니 해가 벌써 서쪽 봉우리에 걸려 있었다. 소매 안쪽 팔뚝에 요괴 발톱 자국이 얼얼하게 남아 있었다."}, {"s": null, "t": "강두철은 법당 처마 밑 화롯가에서 수련생들과 고구마를 굽고 있었다. 나를 보자 부지깽이를 든 채 벌떡 일어났다."}, {"s": "night_office:kang", "t": "왔구나! 어디 보자. 어디를 맞았냐?"}, {"s": null, "t": "나는 소매를 걷어 팔뚝을 보였다. 막으려고 팔을 들었는데 너무 늦게 들어서 발톱이 팔뚝을 긁고 지나갔다고 했다."}, {"s": "night_office:kang", "t": "하하, 잘 맞았다! 맞은 데가 배운 데다. 늦게 들었다는 걸 알았으면 오늘 반은 배운 거다."}, {"s": null, "t": "강두철이 부지깽이로 화롯가 눈밭에 선 하나를 쭉 그었다. 수련생들이 그 선 앞에 쪼르르 모여 앉았다."}, {"s": "night_office:kang", "t": "들어라, 이놈들아. 막는 팔은 맞기 전에 올라가 있어야 한다. 맞고 나서 드는 팔은 막는 팔이 아니라 아픈 팔이다!"}, {"s": null, "t": "수련생 하나가 손을 번쩍 들었다. 아침에 눈밭에 주저앉았던 아이였다."}, {"s": "q:sx_ep_trainee", "t": "교관님, 그럼 언제 들어요? 목검이 너무 빨라서 오는 게 안 보여요."}, {"s": null, "t": "강두철이 부지깽이로 수련생 어깨를 가볍게 톡 건드렸다."}, {"s": "night_office:kang", "t": "목검을 보지 말고 상대 어깨를 봐라. 어깨가 먼저 움직인다. 요괴도 그래. 어깨든 머리든 먼저 움직이는 데가 꼭 있다."}, {"s": null, "t": "강두철이 말을 맺고 나를 돌아보며 눈을 찡긋했다. 나는 설피골 요괴가 덤비기 직전에 머리부터 낮추더라고 했다."}, {"s": "night_office:kang", "t": "거봐라! 맞아 본 사람 말이 제일 정확하다."}, {"s": null, "t": "강두철이 잿불을 뒤적여 군고구마 하나를 꺼냈다. 반으로 툭 쪼개 한쪽을 내게 내밀었다. 노란 속에서 김이 훅 올랐다."}, {"s": "night_office:kang", "t": "먹어라. 맞고 온 사람은 먹고 쉬는 게 먼저다."}, {"s": null, "t": "나는 고구마를 받아 들고 손질해 온 요수 가죽 두 장을 꺼냈다. 강두철이 가죽 귀퉁이를 손끝으로 비벼 두께를 가늠하더니 고개를 끄덕였다."}, {"s": "night_office:kang", "t": "질기구나. 이거면 애들 팔이 남아나겠다. 그런데 이건 내가 받을 게 아니다. 내일 대련에서 네 앞에 설 놈들한테 네가 직접 감아 줘라."}, {"s": "night_office:kang", "t": "오늘 밤은 화롯가에서 몸을 푹 녹여라. 설피골 다녀온 몸이 굳으면 내일 막는 팔이 안 올라간다. 몸 녹이는 것도 수련이다!"}]'::jsonb, '{"xp": 374}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_kangducheol_1', 3, '처마 기둥의 금', '철벽 고찰에서 쉰다, 강화 요수 가죽을(를) 넘긴다', '{"at": ["iron_monastery"], "tasks": [{"t": "rest", "r": ["iron_monastery"], "n": 1}], "give": {"reinforced_leather": 2}}'::jsonb, '[{"s": null, "t": "이튿날 아침, 나는 눈을 쓴 마당에서 목검을 든 수련생들 앞에 섰다. 수련생들 팔마다 내가 감아 준 가죽 덮개가 단단히 매여 있었다."}, {"s": "night_office:kang", "t": "시작! 하나씩 친다. 나머지는 막는 사람 팔을 봐라!"}, {"s": null, "t": "첫 수련생이 목검을 치켜들었다. 나는 그 어깨가 움찔하는 것을 보고 먼저 팔을 들었다. 목검이 가죽 덮개 위에서 탁 막혔다."}, {"s": null, "t": "둘째, 셋째 수련생의 목검이 차례로 날아왔다. 나는 몇 번은 막았고, 한 번은 늦어서 정강이를 맞았다. 수련생들이 킥킥 웃자 강두철이 더 크게 웃었다."}, {"s": "night_office:kang", "t": "웃지 마라, 이놈들아! 저 정강이가 오늘 너희 교본이다!"}, {"s": null, "t": "줄 맨 끝에 어제 주저앉았던 수련생이 섰다. 수련생은 목검을 들고 내 어깨를 노려보았다. 이번에는 눈을 감지 않았다."}, {"s": "q:sx_ep_trainee", "t": "보였어요! 교관님, 어깨가 먼저 움직였어요!"}, {"s": null, "t": "강두철이 커다란 손으로 수련생의 머리를 마구 헝클었다. 수련생이 비틀거리면서도 헤헤 웃었다."}, {"s": null, "t": "대련이 끝나자 강두철은 처마 기둥 앞으로 가서 허리춤의 작은 칼을 꺼냈다. 기둥에는 칼로 그은 짧은 금이 여럿 나란히 나 있었다. 강두철이 그 옆에 새 금을 하나 쓱 그었다."}, {"s": null, "t": "나는 그 금이 무엇이냐고 물었다. 강두철이 칼을 도로 꽂으며 기둥을 손바닥으로 쓸었다."}, {"s": "night_office:kang", "t": "버릇이다. 일을 하나 끝내면 금을 하나 긋는다. 스승님한테서 배웠지. 연무청 기둥에도 내가 부순 목인 수만큼 금이 있다."}, {"s": "night_office:kang", "t": "오늘 금은 저놈이 눈을 안 감은 날 몫이다."}, {"s": null, "t": "강두철이 나를 돌아보았다. 웃음기가 조금 가라앉은 얼굴이었다."}, {"s": "night_office:kang", "t": "애들 갑옷이며 투구가 늘 모자라다. 산에서는 금방 해지거든. 네가 지어 오면 애들 몸에 입히마. 가끔은 물건 말고, 나가서 몇 번이나 막았는지 세어 와도 된다. 그것도 애들한테 들려줄 거다."}, {"s": "night_office:kang", "t": "앞으로도 부탁해도 되겠냐?"}, {"s": null, "t": "나는 그러겠다고 했다. 강두철이 하하 웃으며 내 등을 철썩 쳤다. 등이 얼얼했지만 이번에는 막지 않았다."}]'::jsonb, '{"xp": 374, "gil": 41, "items": {"tonic": 2, "travel_ration": 1}}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('rg_kangducheol_2', 'side', '연담·강두철', '혼자 든 돌', '고찰 뒤 옛 산문 수련장의 버팀돌을 아래 수련 터로 옮기기로 한다. 굴림대로 쓸 나무를 구해 오는 사이를 못 참고 강두철이 혼자 돌을 들다 허리를 삐끗한다. 조사원이 어깨를 받쳐 돌계단을 한 칸씩 함께 내려오고, 수련생들과 굴림대로 돌을 굴려 제자리에 놓는다. 「누구한테 기대 본 건 스승님 뒤로 처음이다.」', 'iron_monastery', 9, '{rg_kangducheol_1}'::text[], null, 1671, '[]'::jsonb, true, null, null)
