update public.world_quests set open_req = '{"regular": "kangducheol", "stage": 2}'::jsonb where quest_id = 'rg_kangducheol_2';
delete from public.world_quest_steps where quest_id = 'rg_kangducheol_2' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_kangducheol_2', 1, '버팀돌', '버팀돌', '{"at": ["iron_monastery"]}'::jsonb, '[{"s": null, "t": "고찰 둘레 솔가지에 얹혔던 눈이 바람에 후드득 떨어졌다. 강두철은 마당 한쪽 멍석 위에 수련생들의 투구와 신을 늘어놓고 하나씩 들여다보고 있었다."}, {"s": "night_office:kang", "t": "왔구나! 봐라, 그사이 네가 지어 온 것들이다. 전립 셋, 쇠징 신 두 켤레, 가죽 철릭 한 벌. 막은 횟수 세어 온 것도 장부에 다 적어 뒀다."}, {"s": "night_office:kang", "t": "쇠징 신이 제일 쓸모 있더라. 눈밭에서 안 미끄러지니까 애들이 막다가 엉덩방아를 덜 찧는다!"}, {"s": null, "t": "강두철이 신 한 켤레를 들어 바닥을 보여 주었다. 쇠징 사이사이에 언 눈이 단단히 박혀 있었다."}, {"s": null, "t": "멍석 곁을 지나던 수련생 하나가 제 발의 쇠징 신을 자랑하듯 발을 쿵쿵 굴렀다."}, {"s": "q:sx_ep_trainee", "t": "이거 신고는 오늘 한 번도 안 넘어졌어요! 교관님은 두 번 넘어지셨고요."}, {"s": null, "t": "강두철의 얼굴이 벌게졌다. 강두철이 멍석의 신 한 짝을 집어 들고 던지는 시늉을 했다."}, {"s": "night_office:kang", "t": "그건 너 막아 주다 그런 거다! 가서 장작이나 패라!"}, {"s": null, "t": "수련생이 키득거리며 달아났다. 강두철이 헛기침을 하고 신을 멍석에 내려놓았다."}, {"s": null, "t": "나는 오늘은 무엇을 하느냐고 물었다. 강두철이 고찰 뒤편 돌계단을 턱으로 가리켰다. 계단은 눈 덮인 솔숲 사이로 가파르게 올라가 있었다."}, {"s": "night_office:kang", "t": "저 위가 옛 산문 수련장이다. 내가 저 애들만 할 때 날마다 기어오르던 데지. 거기 버팀돌이 하나 있다. 그 돌을 어깨로 받치고 버티는 게 산문의 첫 수련이었다."}, {"s": "night_office:kang", "t": "막는다는 건 결국 버티는 거다. 몸으로 무게를 받아 내야 해. 그 돌을 마당 수련 터로 옮겨서 애들한테도 받치게 할 거다."}, {"s": null, "t": "나는 그 돌이 얼마나 무거우냐고 물었다. 강두철이 두 팔을 활짝 벌려 보이다가 멋쩍게 웃었다."}, {"s": "night_office:kang", "t": "장정 넷이 낑낑댈 만하다. 그러니까 굴려야지. 통나무를 밑에 깔고 굴리면 애들 힘으로도 된다."}, {"s": "night_office:kang", "t": "서리솔 고개 솔숲에서 굴림대로 쓸 부적목을 넉넉히 베어 와라. 그런데 그쪽 길이 요즘 수상하다. 서리솔 정령들이 나무 베는 사람을 덮친다더구나."}, {"s": "night_office:kang", "t": "정령 놈들은 눈보라처럼 사방에서 친다. 한쪽만 막으면 다른 쪽으로 맞는다. 몸을 돌려 가며 막는 법을 배우기엔 그만한 상대가 없지. 막다가 틈이 나면 쳐라!"}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_kangducheol_2', 2, '돌계단 한 칸씩', '서리솔 고개에서 부적목을(를) 모은다, 서리솔 정령을(를) 물리친다', '{"at": ["iron_monastery"], "tasks": [{"t": "gather", "items": ["wood"], "r": ["frost_pine_pass"], "n": 4}, {"t": "win", "m": ["r220_pine_1"], "n": 3}]}'::jsonb, '[{"s": null, "t": "부적목 짐을 지고 고찰로 돌아오니 마당이 텅 비어 있었다. 부엌 쪽에서 도마 소리가 통통 울렸다. 수련생들은 모두 저녁 공양 준비를 돕고 있는 모양이었다."}, {"s": null, "t": "뒤편 돌계단 위에서 끄응, 하는 앓는 소리가 들려왔다. 나는 짐을 내려놓고 계단을 뛰어올랐다."}, {"s": null, "t": "계단 중턱에 강두철이 커다란 돌을 품에 안은 채 엉거주춤 서 있었다. 이마에는 땀이 송골송골 맺혔는데, 내뱉는 입김은 하얗게 얼어 흩어졌다."}, {"s": "night_office:kang", "t": "오, 왔구나… 기다리다 좀이 쑤셔서. 조금만 내려 둘까 했지."}, {"s": null, "t": "강두철이 돌을 계단에 내려놓는 순간 허리에서 뚝 소리가 났다. 강두철은 돌 위에 손을 짚은 자세 그대로 굳어 버렸다."}, {"s": "night_office:kang", "t": "…어? 어어? 괜찮다, 아직은 괜찮다! …아이고, 왔다, 이제 왔어!"}, {"s": null, "t": "나는 강두철 곁으로 달려가 겨드랑이 밑으로 어깨를 밀어 넣었다. 강두철의 몸이 내 쪽으로 기우뚱 쏠렸다. 덩치가 커서 혼자 업고 내려갈 수는 없었다."}, {"s": null, "t": "나는 강두철에게 팔을 내 목에 두르라고 하고, 한 칸씩만 내려가자고 했다. 강두철이 이를 악물고 고개를 끄덕였다."}, {"s": null, "t": "우리는 돌계단을 한 칸씩 내려갔다. 내가 먼저 한 발을 내리면 강두철이 내 어깨를 짚고 따라 내렸다. 언 계단이 발밑에서 사각사각 울었다."}, {"s": "night_office:kang", "t": "천천히… 그래, 하나. 둘. 허리 말고 다리… 이거 내가 맨날 애들한테 하던 소리 아니냐. 아이고."}, {"s": null, "t": "계단 아래에 닿자 부엌에서 수련생들이 우르르 뛰어나왔다. 수련생 둘이 강두철의 다른 쪽 팔을 받쳤다."}, {"s": "q:sx_ep_trainee", "t": "교관님! 또 혼자 드셨어요? 혼자 들지 말라고 교관님이 그러셨잖아요!"}, {"s": null, "t": "강두철이 허리를 움켜쥔 채 버럭 소리쳤다. 소리를 지르자 허리가 울렸는지 얼굴이 일그러졌다."}, {"s": "night_office:kang", "t": "시끄럽다! 교관은 예외다! …아니다, 예외 아니다. 너희는 절대 따라 하지 마라."}, {"s": null, "t": "우리는 강두철을 처마 밑 평상에 엎드리게 했다. 고찰 스님 하나가 뜨거운 찜질 수건을 들고 와 강두철 허리에 얹었다. 스님은 합장을 한 번 하고 말없이 돌아갔다."}, {"s": null, "t": "강두철이 엎드린 채 고개만 돌려 계단 쪽을 보았다. 돌은 계단 중턱에 덩그러니 남아 있었다."}, {"s": "night_office:kang", "t": "돌을 저기 두고 밤을 넘기면 계단에 얼어붙는다. 오늘 안에 내려야 해. 네가 베어 온 부적목 말이다, 껍질 벗기고 다듬어서 굴림대 둘만 만들어 줘라."}, {"s": "night_office:kang", "t": "굴리는 건 애들이 한다. 나는… 여기 엎드려서 소리나 지르마."}]'::jsonb, '{"xp": 374}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_kangducheol_2', 3, '기대 본 사람', '가공 부적목을(를) 만든다, 가공 부적목을(를) 넘긴다', '{"at": ["iron_monastery"], "tasks": [{"t": "craft", "items": ["lumber"], "n": 2}], "give": {"lumber": 2}}'::jsonb, '[{"s": null, "t": "해가 지고 횃불을 밝힌 뒤에야 돌이 움직였다. 수련생들이 굴림대 둘을 번갈아 돌 밑에 밀어 넣었다. 나는 돌 옆에 붙어 서서 돌이 기울지 않게 받쳤다."}, {"s": "night_office:kang", "t": "앞에 하나 깔고! 뒤에 빠진 거 앞으로! 그렇지! 밀지 말고 굴려라!"}, {"s": null, "t": "돌이 드르륵드르륵 굴림대를 타고 내려갔다. 마지막 계단에서 돌이 쿵 마당에 내려앉자 수련생들이 와아 소리를 질렀다."}, {"s": null, "t": "강두철은 평상에 엎드린 채 두 주먹을 불끈 쥐어 올렸다. 그 바람에 허리가 울렸는지 으윽 신음을 삼켰다."}, {"s": null, "t": "밤이 깊자 수련생들은 하나둘 승방으로 들어갔다. 나는 화로를 평상 곁으로 끌어다 놓았다. 숯불이 탁탁 튀며 강두철의 옆얼굴을 붉게 비췄다."}, {"s": null, "t": "나는 화로에 숯을 한 덩이 더 얹었다. 강두철이 엎드린 채 팔을 뻗어 곱은 손을 화로 위에 쬐었다."}, {"s": null, "t": "강두철이 엎드린 채 화로 불을 보다가 입을 열었다. 목소리가 낮에 비해 한결 작았다."}, {"s": "night_office:kang", "t": "…아까 계단에서 말이다. 누구한테 기대 본 건 스승님 뒤로 처음이다."}, {"s": "night_office:kang", "t": "늘 내가 업는 쪽이었거든. 쓰러진 놈만 보면 몸이 먼저 나가. 그러다 보니 기대는 법을 까먹었지."}, {"s": null, "t": "나는 기대는 것도 버티는 것만큼 배워야 하는 것 같다고 했다. 강두철이 화로 쪽으로 고개를 돌린 채 한참 아무 말도 하지 않았다."}, {"s": "night_office:kang", "t": "…하하, 그 말 애들한테 써먹어도 되냐? 네가 했다고는 안 할 거다."}, {"s": null, "t": "나는 마음대로 하라고 했다. 강두철이 엎드린 채 팔을 뻗어 평상 다리에 손톱으로 짧은 금을 그었다."}, {"s": "night_office:kang", "t": "이건 오늘 몫이다. 돌 내린 날. …그리고 기댄 날."}, {"s": null, "t": "나는 승방에서 솜이불을 한 채 가져와 강두철의 어깨에 덮었다. 강두철이 이불 끝을 턱밑까지 끌어당기며 눈을 감았다."}, {"s": null, "t": "화롯불이 사그라들 때까지 나는 평상 곁에 앉아 있었다. 이윽고 강두철의 코 고는 소리가 처마 밑을 드르렁드르렁 울렸다."}]'::jsonb, '{"xp": 374, "gil": 41, "items": {"tonic": 2, "travel_ration": 1}}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('rg_kangducheol_3', 'side', '연담·강두철', '스승의 목인', '강두철은 연무장에서 쓰러진 스승의 목인장에서 팔 한 짝을 건져 산까지 짊어지고 왔다. 산문 수련 터에 새 목인을 세우고 그 팔을 달기로 한다. 몸통을 깎기 전에 둘이 목검으로 대련하고, 강두철이 조사원의 막는 버릇을 짚어 준다. 새 목인이 서자 강두철이 스승과 첫 금 이야기를 꺼낸다.', 'iron_monastery', 9, '{rg_kangducheol_2}'::text[], null, 1672, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
