delete from public.world_quest_steps where quest_id = 'rg_kangducheol_3' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_kangducheol_3', 1, '나무 팔 한 짝', '나무 팔 한 짝', '{"at": ["iron_monastery"]}'::jsonb, '[{"s": null, "t": "고찰 마당 수련 터 한가운데 지난번에 굴려 내린 버팀돌이 자리를 잡고 있었다. 돌 등이 수련생들 어깨에 닳아 벌써 반들반들했다."}, {"s": null, "t": "강두철은 돌 곁에 앉아 무릎 위에 얹은 무언가를 천으로 닦고 있었다. 허리는 다 나았는지 앉은 자세가 꼿꼿했다."}, {"s": "night_office:kang", "t": "왔구나. 요즘 네가 지어 온 것들 말이다. 두정갑은 맏이한테 입혔고, 흑립은 제일 작은 놈이 쓰면 머리가 커 보인다고 서로 쓰겠다더라."}, {"s": "night_office:kang", "t": "막은 횟수 적어 온 장부는 애들이 돌려 읽는다. 「오늘 막은 수」가 저희끼리 내기가 됐어!"}, {"s": null, "t": "나는 허리는 괜찮으냐고 물었다. 강두철이 앉은 채 허리를 좌우로 비틀어 보이며 씩 웃었다."}, {"s": "night_office:kang", "t": "멀쩡하다! 그날 네 어깨 덕이다. 애들한테는 계단 반은 혼자 내려왔다고 해 뒀으니 입 다물어라."}, {"s": null, "t": "강두철이 무릎 위의 것을 들어 보였다. 손때가 까맣게 밴 나무 팔 한 짝이었다. 팔꿈치 마디에 쇠 고리가 박혀 있었다."}, {"s": null, "t": "나는 그 팔을 알아보았다. 연무장에서 내가 쓰러뜨린 팔괘진 목인장의 팔이었다."}, {"s": "night_office:kang", "t": "알아보는구나. 스승님이 손수 깎으신 목인장 팔이다. 네가 눕힌 날 몸통은 쪼개졌는데 이 팔은 멀쩡하더라. 버리지를 못하고 여기까지 짊어지고 왔다."}, {"s": "night_office:kang", "t": "산문 수련 터에 새 목인을 하나 세울 거다. 몸통은 새로 깎고, 팔은 이걸 단다. 스승님 팔로 애들 막는 걸 받아 주라고."}, {"s": null, "t": "강두철이 팔꿈치 쇠 고리 둘레를 엄지로 쓸었다. 그 자리에 칼끝으로 그은 듯한 자국이 희미하게 남아 있었다."}, {"s": null, "t": "나는 몸통은 무엇으로 깎느냐고 물었다. 강두철이 버팀돌을 손바닥으로 탕탕 쳤다."}, {"s": "night_office:kang", "t": "질겨야 한다. 애들이 하루에 몇백 번씩 친다. 그냥 부적목은 한 철을 못 버텨. 수지를 먹여 단단하게 다진 부적목이어야지."}, {"s": "night_office:kang", "t": "설피골 숲에 부적목 수지가 엉겨 붙은 나무들이 있다. 수지를 넉넉히 받아다가 부적목을 다져서 두 토막만 만들어 와라. 나는 그동안 이 팔을 손질해 두마."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_kangducheol_3', 2, '제 눈엔 안 보이는 것', '설피골에서 부적목 수지을(를) 모은다, 강화 부적목을(를) 만든다, 강화 부적목을(를) 넘긴다', '{"at": ["iron_monastery"], "tasks": [{"t": "gather", "items": ["resin"], "r": ["snow_hollow"], "n": 3}, {"t": "craft", "items": ["reinforced_lumber"], "n": 2}], "give": {"reinforced_lumber": 2}}'::jsonb, '[{"s": null, "t": "다진 부적목 두 토막을 내려놓자 강두철이 토막 끝을 손톱으로 꾹 눌러 보았다. 손톱 자국이 하나도 남지 않았다."}, {"s": "night_office:kang", "t": "됐다. 이거면 애들 손목이 먼저 나가겠다. 내일 아침에 같이 깎자."}, {"s": null, "t": "강두철이 일어나 수련 터 가장자리에 세워 둔 목검 두 자루를 집어 들었다. 그중 한 자루를 내게 휙 던졌다. 나는 허둥지둥 목검을 받았다."}, {"s": null, "t": "처마 밑에서 장작을 나르던 수련생들이 걸음을 멈추고 쪼르르 모여들었다."}, {"s": "night_office:kang", "t": "몸통 깎기 전에 한 판 하자. 목인한테 애들 막는 걸 맡기려면, 사람이 사람을 막는 걸 먼저 봐 둬야지."}, {"s": null, "t": "강두철이 목검을 비스듬히 들었다. 순식간에 웃음기가 가시고 눈매가 매서워졌다. 마당의 찬 공기마저 팽팽해지는 것 같았다."}, {"s": null, "t": "첫 목검이 휘익 날아왔다. 나는 팔을 들어 막았다. 둘째도 막았다. 셋째에서 강두철이 갑자기 몸을 낮췄고, 목검 끝이 내 옆구리에 툭 닿았다."}, {"s": "night_office:kang", "t": "거기다. 너는 막을 때 {직업:호위=방패를 너무 높이 쳐든다. 위는 막는데 옆구리가 텅 빈다/월궁=활 쥔 팔부터 감싼다. 활을 지키려다 몸이 빈다/퇴마=진언부터 떠올리느라 눈이 늦다. 입보다 눈이 먼저다/의무=다친 데부터 살핀다. 맞기 전엔 맞을 데를 봐야지/봉인=발을 딱 붙이고 선다. 막을 때도 발은 움직여야 한다/암영=한 발 물러나며 피하려 든다. 막을 땐 버텨야 한다/혈기=피 갑주부터 두르려다 팔이 늦다. 갑주보다 팔이 먼저 올라가야 한다/여명=창을 내밀어 막으려 든다. 창끝은 멀어도 네 몸은 가깝다/조련=동무부터 돌아본다. 네가 먼저 서 있어야 동무도 지킨다/진법=산가지부터 늘어놓으려 든다. 진보다 팔이 먼저다/*=맞기 직전에 왼발이 뒤로 빠진다. 발이 빠지면 막는 팔도 같이 빠진다}."}, {"s": null, "t": "나는 그런 줄 몰랐다고 했다. 강두철이 목검으로 제 어깨를 툭툭 두드렸다."}, {"s": "night_office:kang", "t": "버릇은 제 눈엔 안 보인다. 나도 스승님한테 같은 소리를 백 번은 들었다. 「두철아, 너는 막을 때 턱이 들린다.」 그 소리 듣기 싫어서 턱을 당기다 보니 목이 이렇게 됐지!"}, {"s": null, "t": "강두철이 제 턱을 손가락으로 툭 쳐 보였다. 굵은 목에 턱이 단단히 묻혀 있었다. 나도 모르게 웃음이 났고, 강두철이 따라서 껄껄 웃었다."}, {"s": null, "t": "우리는 그 뒤로 몇 판을 더 겨뤘다. 해가 기울어 수련 터에 그림자가 길게 눕자 강두철이 목검을 내렸다. 둘 다 이마에서 김이 모락모락 올랐다."}, {"s": "night_office:kang", "t": "버릇은 말로 안 고쳐진다. 맞아 가며 고쳐야 해. 설피골 얼음 껍질 오소리 놈들은 머리를 들이밀고 곧장 들이받는다. 늘 같은 데로 오니까 버릇 고치기에 딱 좋다."}, {"s": "night_office:kang", "t": "그놈들 앞에서 내가 짚은 데를 생각하며 막아 봐라. 고쳐졌는지는 네 몸이 먼저 안다."}]'::jsonb, '{"xp": 374}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_kangducheol_3', 3, '스승님 팔', '얼음 껍질 오소리을(를) 물리친다, 강화 부적목을(를) 넘긴다', '{"at": ["iron_monastery"], "tasks": [{"t": "win", "m": ["r71_snow_3"], "n": 3}], "give": {"reinforced_lumber": 2}}'::jsonb, '[{"s": null, "t": "이튿날 아침, 강두철과 나는 수련 터에서 부적목 토막을 깎았다. 강두철이 끌을 대면 나는 토막이 구르지 않게 양 끝을 붙잡았다. 대팻밥이 눈 위에 사락사락 쌓였다."}, {"s": null, "t": "해가 중천에 오를 무렵 사람 키만 한 몸통이 섰다. 강두철이 나무 팔을 어깨 자리에 대고 쇠 고리를 끼웠다. 나는 팔이 처지지 않게 아래에서 받쳐 들었다."}, {"s": "night_office:kang", "t": "…스승님, 새 몸입니다. 북쪽이라 좀 추우실 겁니다."}, {"s": null, "t": "강두철이 목인 어깨를 손바닥으로 두어 번 쓸었다. 목소리가 평소와 달리 낮았다."}, {"s": "night_office:kang", "t": "자, 해 보자. 이번엔 거꾸로다. 목인이 치고 네가 막는다."}, {"s": null, "t": "강두철이 목인 뒤에 서서 나무 팔을 잡아당겼다가 놓았다. 쇠 고리가 끼익 돌며 나무 팔이 휘익 날아왔다."}, {"s": null, "t": "나는 어제 짚인 데를 떠올리며 막았다. 나무 팔이 내 팔에 퍽 둔탁하게 걸렸다. 이번에는 몸이 빠지지 않았다."}, {"s": "night_office:kang", "t": "하하, 고쳐졌다! 오소리들한테 고맙다고 해야겠구나!"}, {"s": null, "t": "나는 팔뚝을 문지르며 오소리들한테 받은 멍이 아직 덜 빠졌다고 했다. 강두철이 소매에서 고약 한 통을 꺼내 내 손에 툭 쥐여 주었다."}, {"s": "night_office:kang", "t": "내 허리에 붙이던 거다. 반 남았다. 멍에도 듣는다."}, {"s": null, "t": "나는 스승님은 어떤 분이었느냐고 물었다. 강두철이 목인 팔을 붙잡아 멈추고 팔꿈치를 내려다보았다."}, {"s": "night_office:kang", "t": "말이 적은 분이었다. 이 산문에서 나를 데리고 내려가 연무청에 세우셨지. 칼 쓰는 법은 산문에서 이미 배웠으니, 너는 막는 것만 배우라고 하셨다."}, {"s": "night_office:kang", "t": "처음 석 달은 맞기만 했다. 이 팔한테. 밤마다 멍든 데를 세다가 잠들었지. 그러다 처음 막은 날, 스승님이 연무청 기둥에 금을 하나 그어 주셨다. 그게 내 첫 금이다."}, {"s": null, "t": "강두철이 팔꿈치에 남은 희미한 자국을 엄지로 쓸었다. 가까이서 보니 칼끝으로 그은 짧은 금 하나였다."}, {"s": "night_office:kang", "t": "스승님은 당신 목인에도 금을 그으셨던 모양이다. 연무청 기둥에는 스승님 금 위로 내 금이 쭉 이어져 있다. 언젠가 내려가면 보여 주마."}, {"s": null, "t": "강두철이 목인 팔을 놓았다. 나무 팔이 천천히 흔들리다 멎었다. 북쪽 바람이 솔숲을 쏴아 훑고 지나갔다."}]'::jsonb, '{"xp": 374, "gil": 41, "items": {"tonic": 2, "travel_ration": 1}}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('rg_kangducheol_4', 'side', '연담·강두철', '먼저 막아선 사람', '이번 겨울에 들어온 막내에게 맞는 갑옷이 없어 조사원이 가죽 철릭을 짓는다. 마지막 대련 날, 강두철이 목인 팔을 당기고 조사원이 아이들 곁에 선다. 막내가 미끄러져 넘어지고 나무 팔이 휘둘러 오자 강두철보다 조사원이 먼저 막내 앞을 막아선다. 강두철이 한참 보다가 웃음을 터뜨린다.', 'iron_monastery', 9, '{rg_kangducheol_3}'::text[], null, 1673, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = '{"regular": "kangducheol", "stage": 4}'::jsonb where quest_id = 'rg_kangducheol_4';
delete from public.world_quest_steps where quest_id = 'rg_kangducheol_4' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_kangducheol_4', 1, '소매가 무릎까지', '소매가 무릎까지', '{"at": ["iron_monastery"]}'::jsonb, '[{"s": null, "t": "철벽 고찰에 눈보라가 사흘째 몰아쳤다. 처마마다 바람에 날린 눈이 수북이 쌓였고, 수련 터 목인의 어깨에도 눈이 하얗게 얹혀 있었다."}, {"s": null, "t": "강두철은 법당 처마 밑에서 수련생들 갑옷 끈을 하나씩 고쳐 매 주고 있었다. 나를 보자 끈을 쥔 손을 번쩍 들었다."}, {"s": "night_office:kang", "t": "왔구나! 그사이 네가 지어 온 수결 도포 말이다, 맏이가 아주 끼고 산다. 야행 경의는 빨아 널었더니 애들끼리 서로 입겠다고 싸웠고!"}, {"s": null, "t": "처마 밑에 줄지어 앉은 수련생들이 저마다 제 옷깃을 내려다보며 히죽거렸다."}, {"s": null, "t": "강두철이 처마 끝에 홀로 웅크린 수련생 하나를 턱으로 가리켰다. 다른 아이들보다 머리 하나는 작았다. 얇은 누비옷 위로 어깨가 바들바들 떨렸다."}, {"s": null, "t": "내가 그쪽을 보자 막내가 얼른 고개를 숙였다. 귀 끝이 추위에 새빨갰다."}, {"s": "night_office:kang", "t": "저놈이 이번 겨울에 새로 들어온 막내다. 갑옷이 하나도 안 맞아. 맏이 것을 줄여 입혔더니 소매가 무릎까지 내려온다."}, {"s": "night_office:kang", "t": "내일이 마지막 대련이다. 목인 앞에서 한 사람씩 막는 날이지. 저놈만 맨몸으로 세울 수는 없잖냐. 몸에 맞는 가죽 철릭 한 벌만 지어 다오."}, {"s": null, "t": "나는 맏이 것을 한 번 더 줄이면 안 되느냐고 물었다. 강두철이 머리를 긁적였다."}, {"s": "night_office:kang", "t": "벌써 두 번 줄였다. 세 번 줄이면 맏이가 입을 게 없어!"}, {"s": null, "t": "나는 막내의 어깨 너비를 눈으로 가늠했다. 강두철이 고개를 끄덕이더니 목소리를 낮췄다."}, {"s": "night_office:kang", "t": "하나 더 있다. 대련 날엔 내가 목인 팔을 당긴다. 그러면 애들 곁에 붙어 설 사람이 없어. 네가 서 다오. 누가 넘어지면 앞을 막아 줄 사람으로."}, {"s": "night_office:kang", "t": "남을 등 뒤에 두고 막는 건 혼자 막는 거랑 또 다르다. 내가 비키면 뒤에 선 놈이 맞으니까. 설피골 망령들은 앞사람을 지나쳐 뒤에 선 사람부터 노린다."}, {"s": "night_office:kang", "t": "그놈들 앞에 서 봐라. 등 뒤에 누가 있다고 치고 서는 거다. 그러면 등 뒤를 지키는 감이 온다."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_kangducheol_4', 2, '대련 전날 밤', '설피 신은 망령을(를) 물리친다, 가죽 철릭을(를) 만든다, 가죽 철릭을(를) 넘긴다', '{"at": ["iron_monastery"], "tasks": [{"t": "win", "m": ["r71_snow_4"], "n": 3}, {"t": "craft", "items": ["a2_light"], "n": 1}], "give": {"a2_light": 1}}'::jsonb, '[{"s": null, "t": "설피골에서 돌아오니 눈보라가 잦아들어 있었다. 강두철은 승방 아궁이 앞 나무 걸상에 앉아 장작을 밀어 넣고 있었다. 아궁이에서 매캐한 솔가지 연기가 피어올랐다."}, {"s": "night_office:kang", "t": "왔구나. 망령들은 어떻더냐? 뒤를 노리던가?"}, {"s": null, "t": "나는 망령 하나가 내 옆을 스르르 빠져나가려 해서 몸을 틀어 막았다고 했다. 등 뒤에 아무도 없는데도 누가 있는 것처럼 등이 서늘했다고 덧붙였다."}, {"s": "night_office:kang", "t": "하하, 그 서늘한 게 감이다. 등 뒤에 사람을 두면 늘 그렇다. 그걸 잊으면 막는 사람이 아니다."}, {"s": null, "t": "나는 걸상 옆 땔감 더미에 걸터앉았다. 강두철이 아궁이 곁 주전자에서 보리차를 한 사발 따라 내게 건넸다. 사발이 손바닥에 뜨끈했다."}, {"s": null, "t": "나는 지어 온 가죽 철릭을 꺼냈다. 강두철이 철릭 소매를 쭉 펴서 제 팔에 대 보더니 껄껄 웃었다. 소매가 강두철 팔꿈치에도 못 미쳤다."}, {"s": "night_office:kang", "t": "막내 팔에 딱이겠다. 이건 내가 줄 게 아니라 네가 줘라. 오늘 밤 승방에 가서 직접 입혀 줘. 내일 앞에 서 줄 사람한테 받은 옷이어야 저놈이 덜 떤다."}, {"s": null, "t": "강두철이 장작 하나를 더 밀어 넣었다. 아궁이 불빛에 얼굴 반쪽이 붉게 물들었다."}, {"s": "night_office:kang", "t": "내일은 나도 좀 떨린다. 막내가 처음 목인 앞에 서는 날이거든. 스승님 팔이 생각보다 세다."}, {"s": null, "t": "강두철이 제 팔뚝을 슬슬 문질렀다. 오래전 멍이라도 떠오른 듯한 손길이었다."}, {"s": null, "t": "나는 그렇다면 교관이 직접 막내 곁에 서면 되지 않느냐고 물었다. 강두철이 고개를 저었다."}, {"s": "night_office:kang", "t": "목인 팔은 당기는 손이 늦으면 더 세게 돈다. 그 손은 내가 맡아야 해. 대신 네가 곁에 서 있으면 나는 손만 보면 된다."}, {"s": null, "t": "승방 문틈으로 막내가 고개를 빼꼼 내밀었다가 우리와 눈이 마주치자 쏙 들어갔다."}, {"s": "night_office:kang", "t": "봐라, 저놈도 못 자고 있다. 얼른 가서 입혀 주고 너도 일찍 자 둬라. 막는 사람이 졸면 큰일이다."}]'::jsonb, '{"xp": 374}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_kangducheol_4', 3, '먼저 막아선 사람', '철벽 고찰에서 쉰다, 가죽 철릭을(를) 넘긴다', '{"at": ["iron_monastery"], "tasks": [{"t": "rest", "r": ["iron_monastery"], "n": 1}], "give": {"a2_light": 1}}'::jsonb, '[{"s": null, "t": "대련 날 아침은 하늘이 쨍하게 맑았다. 수련 터 둘레에 수련생들이 줄지어 섰고, 고찰 스님 몇이 마당 끝에서 구경했다. 막내는 내가 입혀 준 가죽 철릭을 입고 줄 맨 끝에 서 있었다."}, {"s": null, "t": "강두철이 목인 뒤에 서서 나무 팔을 잡아당겼다. 맏이부터 차례로 목인 앞에 섰고, 나무 팔이 휘익 돌 때마다 가죽 덮개 위에서 퍽퍽 소리가 났다."}, {"s": "night_office:kang", "t": "좋다! 다음! 이 목인은 어깨가 없으니 내 손을 봐라!"}, {"s": null, "t": "막내 차례가 왔다. 막내가 목인 앞에 서서 팔을 들었다. 무릎이 덜덜 떨렸다. 나는 막내 왼쪽 한 걸음 뒤에 섰다."}, {"s": null, "t": "강두철이 팔을 당겼다 놓았다. 그 순간 막내의 발이 언 땅에서 쭉 미끄러졌다. 막내가 뒤로 벌러덩 넘어졌고, 나무 팔은 벌써 휘익 돌아오고 있었다."}, {"s": "night_office:kang", "t": "막내야!"}, {"s": null, "t": "강두철이 손을 놓고 뛰쳐나오려 했다. 나는 그보다 먼저 막내 앞으로 뛰어들었다. 두 팔을 모아 올리고 왼발로 언 땅을 버텼다."}, {"s": null, "t": "나무 팔이 내 팔뚝에 쾅 부딪혔다. 팔이 저릿했지만 발은 한 치도 빠지지 않았다. 나무 팔이 끼이익 소리를 내며 내 팔에 걸려 멎었다."}, {"s": null, "t": "마당이 쥐 죽은 듯 조용해졌다. 나는 막내를 일으켜 세우며 다친 데가 없느냐고 물었다. 막내가 눈을 동그랗게 뜨고 제 팔다리를 더듬어 보았다."}, {"s": "q:sx_ep_trainee", "t": "…안 맞았어요. 하나도 안 맞았어요!"}, {"s": null, "t": "강두철은 반쯤 뛰쳐나온 자세 그대로 서 있었다. 두 손이 허공에 엉거주춤 멈춰 있었다. 강두철이 나와 막내와 목인을 한참 번갈아 보았다."}, {"s": null, "t": "이윽고 강두철의 어깨가 들썩이기 시작했다. 들썩임은 곧 웃음이 되어 터져 나왔다."}, {"s": "night_office:kang", "t": "하하하! 봤냐, 이놈들아! 교관보다 먼저 막아섰다! 교관은 아직 반도 못 나왔는데!"}, {"s": null, "t": "수련생들이 와 소리를 지르며 막내에게 달려들었다. 강두철은 웃음을 그치지 못하고 목인 어깨에 이마를 기댔다."}, {"s": "night_office:kang", "t": "스승님, 보셨습니까? 저보다 빠른 놈이 나왔습니다."}, {"s": null, "t": "강두철이 목인에서 이마를 떼고 나를 보았다. 웃음 때문인지 눈가가 젖어 있었다. 강두철은 허리춤의 칼을 꺼내 처마 기둥 앞으로 가다가 멈칫했다."}, {"s": "night_office:kang", "t": "…아니다. 이건 여기 고찰 기둥에 그을 금이 아니다. 금 하나로는 모자라."}, {"s": null, "t": "강두철이 칼을 도로 꽂았다. 막내는 내 소매를 꼭 붙잡은 채 놓지 않았다."}]'::jsonb, '{"xp": 374, "gil": 41, "items": {"tonic": 2, "travel_ration": 1}}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('rg_kangducheol_5', 'side', '연담·강두철', '기둥의 금', '눈이 녹아 산문 수련이 끝나고, 강두철이 스승의 목인을 수레에 싣고 수련생들과 하산한다. 조사원이 먼저 연무장에 내려가 겨우내 깨어난 목인귀들을 살피고, 아이들 앞에서 막고 이긴다. 그날 밤 연무청 기둥, 부순 목인 수 옆에 강두철이 새 금을 긋고 그 밑에 조사원 이름을 새긴다. 「여긴 내가 가르친 놈 중에 나보다 먼저 막아선 놈 자리다!」 산에서 밤마다 깎은 작은 수련 목인을 건넨다.', 'iron_monastery', 9, '{rg_kangducheol_4}'::text[], null, 1674, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = '{"regular": "kangducheol", "stage": 5}'::jsonb where quest_id = 'rg_kangducheol_5';
delete from public.world_quest_steps where quest_id = 'rg_kangducheol_5' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_kangducheol_5', 1, '하산', '하산', '{"at": ["iron_monastery"]}'::jsonb, '[{"s": null, "t": "철벽 고찰 처마 끝 고드름이 뚝뚝 녹아 떨어지고 있었다. 산 아래에서 올라온 바람에 물기 머금은 흙냄새가 섞여 있었다."}, {"s": null, "t": "수련 터에서는 수련생들이 짐을 꾸리고 있었다. 스승의 목인은 짚에 싸인 채 수레에 실려 있었다. 수레바퀴에 쐐기를 박던 강두철이 나를 보고 일어섰다."}, {"s": "night_office:kang", "t": "왔구나! 그사이 네가 지어 온 것들 덕에 올겨울엔 갑옷 해져서 우는 놈이 하나도 없었다. 정자관은 맏이가 하산 길에 쓰고 가겠단다. 체면 차린다고!"}, {"s": "night_office:kang", "t": "막은 횟수 적은 장부도 다 챙겼다. 연무청에 내려가서 다음 애들한테 읽힐 거다."}, {"s": null, "t": "수레 곁에서 막내가 내게 손을 흔들었다. 내가 지어 준 가죽 철릭 소매가 손목에 꼭 맞았다."}, {"s": "q:sx_ep_trainee", "t": "조사원님! 저 이제 목인 앞에서 눈 안 감아요! 교관님이 그러셨어요, 제가 제일 늦게 감는대요!"}, {"s": null, "t": "강두철이 쐐기 망치를 든 채 껄껄 웃었다."}, {"s": "night_office:kang", "t": "늦게 감는 거랑 안 감는 건 다르다, 이놈아! 짐이나 마저 묶어라!"}, {"s": null, "t": "나는 벌써 내려가느냐고 물었다. 강두철이 녹아내리는 고드름을 올려다보았다."}, {"s": "night_office:kang", "t": "눈이 녹으면 산문 수련은 끝이다. 길이 질어지기 전에 내려가야 해. 스승님 목인도 데리고 간다. 연무청에 세울 거다."}, {"s": null, "t": "강두철이 짚에 싸인 목인 어깨를 툭툭 두드렸다. 짚 사이로 나무 팔 끝이 삐죽 나와 있었다."}, {"s": "night_office:kang", "t": "애들 걸음으로는 연무장까지 며칠 걸린다. 그런데 연무장이 겨울 내내 비어 있었으니 목인귀 놈들이 또 설치고 있을 거다. 스승님 목인장이 없으니 대장 없는 놈들이 제멋대로겠지."}, {"s": "night_office:kang", "t": "네가 먼저 내려가서 연무장을 살펴 다오. 어디가 무너졌는지, 목인귀가 몇이나 깨어 있는지. 애들을 데리고 들어가다가 덮치면 곤란하니까."}, {"s": null, "t": "나는 연무장에 먼저 내려가 있겠다고 했다. 강두철이 고개를 끄덕이고 내 어깨에 손을 얹었다. 손이 묵직하고 따뜻했다."}, {"s": "night_office:kang", "t": "그리고 연무청 기둥 말이다. 보여 주겠다던 거, 이번에 보여 주마. 먼저 가서 기다려라."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_kangducheol_5', 2, '금만 있는 기둥', '연무장·팔괘진에 간다, 연무장·팔괘진을(를) 살핀다', '{"at": ["hq_training"], "tasks": [{"t": "travel", "r": ["hq_training"], "n": 1}, {"t": "search", "r": ["hq_training"], "n": 2}]}'::jsonb, '[{"s": null, "t": "연무장에 닿은 지 사흘째 되는 날 저녁, 문밖에서 수레바퀴 소리가 덜컹덜컹 들려왔다. 강두철이 수련생들을 이끌고 연무장 문을 들어섰다. 산에서 내려온 사람들의 신발이 진흙투성이였다."}, {"s": null, "t": "나는 연무장 우물에서 길어 둔 물을 수련생들에게 한 바가지씩 떠 주었다. 강두철도 바가지째 꿀꺽꿀꺽 들이켰다."}, {"s": "night_office:kang", "t": "어떠냐? 몇 놈이냐?"}, {"s": null, "t": "나는 팔괘진 한가운데에 목인귀들이 모여 웅크리고 있더라고 했다. 대장이 없어서인지 서로 엉켜 엎치락뒤치락하더라고 덧붙였다."}, {"s": "night_office:kang", "t": "하하, 대장 없는 놈들은 늘 저렇다. 우리 애들도 내가 없으면 저래."}, {"s": null, "t": "수련생들 사이에서 투덜대는 소리가 들렸다. 강두철은 못 들은 척 수레를 연무청 처마 밑으로 끌었다."}, {"s": null, "t": "연무청 마루 앞에 굵은 기둥 하나가 서 있었다. 기둥 아래쪽부터 칼로 그은 짧은 금들이 빼곡했다. 맨 아래 금 하나만 다른 금들보다 깊고 길었다."}, {"s": null, "t": "강두철이 기둥 앞에 서서 그 금을 한참 올려다보았다. 산에서 쩌렁쩌렁하던 목소리가 쑥 들어가 있었다."}, {"s": "night_office:kang", "t": "저게 스승님이 그어 주신 첫 금이다. 그 위로는 다 내 거고. 부순 목인 수만큼, 끝낸 일만큼 그었다."}, {"s": null, "t": "나는 금만 있고 이름은 하나도 없느냐고 물었다. 강두철이 기둥을 손바닥으로 쓸어 올렸다."}, {"s": "night_office:kang", "t": "금에는 이름을 안 단다. 연무청 기둥에 이름을 새기는 건 따로 정한 자리가 있을 때뿐이다. 스승님도 내 이름은 안 새기셨다."}, {"s": null, "t": "강두철은 그 말을 하고 기둥에서 손을 뗐다. 무언가 더 말하려다 입을 다문 얼굴이었다."}, {"s": null, "t": "팔괘진 쪽에서 나무끼리 부딪는 소리가 딱딱 울렸다. 수련생들이 움찔하며 강두철 뒤로 모여들었다."}, {"s": "night_office:kang", "t": "일단 저놈들부터 치워야 애들이 잔다. 마지막 수련이다. 애들 앞에서 막고 이겨 봐라. 산에서 배운 걸 애들이 네 몸으로 다시 보게."}]'::jsonb, '{"xp": 374}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_kangducheol_5', 3, '기둥의 금', '목인귀을(를) 물리친다', '{"at": ["hq_training"], "tasks": [{"t": "win", "m": ["m_01"], "n": 4}]}'::jsonb, '[{"s": null, "t": "마지막 목인귀가 쓰러지자 수련생들이 연무장 담 위에서 우르르 뛰어내렸다. 팔괘진 한가운데 부서진 나무 조각들이 흩어져 있었다."}, {"s": null, "t": "그날 밤 수련생들이 연무청 처마 밑에 스승의 목인을 세웠다. 강두철이 나무 팔을 끼웠고, 나는 아래에서 받쳐 들었다. 북쪽에서 함께 내려온 목인이 연무장 등불 아래 섰다."}, {"s": null, "t": "수련생들이 잠든 뒤 강두철이 기둥 앞으로 나를 불렀다. 강두철의 손에 작은 칼 한 자루가 쥐여 있었다."}, {"s": "night_office:kang", "t": "산에서 금 하나로는 모자란다고 했지. 오늘 그 셈을 하자."}, {"s": null, "t": "강두철이 기둥 맨 위 금 옆에 새 금을 하나 그었다. 칼끝이 나무를 파고드는 소리가 사각사각 났다. 강두철은 칼을 내리지 않고 그 금 밑에 글자를 새기기 시작했다."}, {"s": null, "t": "강두철은 한 획씩 천천히 새겨 나갔다. 등불 아래 기둥에 내 이름이 드러났다. 강두철이 칼을 거두고 새긴 글자를 손가락으로 쓸었다."}, {"s": "night_office:kang", "t": "{이름}."}, {"s": null, "t": "강두철이 내 이름을 처음으로 불렀다. 늘 쩌렁쩌렁하던 목소리가 그 한마디만은 낮았다."}, {"s": "night_office:kang", "t": "여긴 내가 가르친 놈 중에 나보다 먼저 막아선 놈 자리다! {등급}이든 신참이든, 이 기둥 앞에선 그냥 {이름}이다.", "fac": "night_office", "rank": [1, 4], "spec": 0, "grp": 1}, {"s": "night_office:kang", "t": "여긴 내가 가르친 사람 중에 나보다 먼저 막아선 사람 자리요! 판관 나리든 신참이든, 이 기둥 앞에선 그냥 {이름}이오.", "fac": "night_office", "rank": [5, 5], "spec": 0, "grp": 1}, {"s": "night_office:kang", "t": "여긴 내가 가르친 놈 중에 나보다 먼저 막아선 놈 자리다! 남의 식구라도 상관없다. 이 기둥 앞에선 그냥 {이름}이다.", "fac_not": "night_office", "spec": 2, "grp": 1}, {"s": null, "t": "나는 이름을 새기는 자리가 따로 있다더니 그게 이 자리냐고 물었다. 강두철이 하하 웃으며 뒷머리를 긁었다."}, {"s": "night_office:kang", "t": "방금 정했다! 교관이 정하면 자리가 된다. 스승님도 아마 그러셨을 거다."}, {"s": "night_office:kang", "t": "이제 연무청 기둥에 새긴 이름이다. 지우려면 기둥을 뽑아야 할 거다!"}, {"s": null, "t": "강두철이 마루 밑에서 짚으로 싼 무언가를 꺼냈다. 짚을 풀자 무릎 높이만 한 작은 목인이 나왔다. 팔꿈치 마디에 작은 쇠 고리가 박혀 있었다."}, {"s": "night_office:kang", "t": "산에서 밤마다 깎았다. 스승님 목인 깎고 남은 네 부적목으로. 수련 목인이다. 네가 머무는 방 한구석에 세워 둬라. 가끔 쳐 보고, 가끔 맞아도 보고."}, {"s": null, "t": "나는 작은 목인을 받아 들었다. 생각보다 묵직했다. 목인 가슴께에 칼끝으로 그은 짧은 금 하나가 있었다."}, {"s": "night_office:kang", "t": "그 금은 네 첫 금이다. 막내 앞을 막아선 날 몫. …맞는 법 잊지 마라. 맞는 법은 평생이다."}, {"s": null, "t": "연무장 너머 정청 쪽에서 밤 순라 북소리가 둥둥 울렸다. 강두철은 기둥에 새긴 내 이름을 손바닥으로 한 번 더 쓸고 나서야 등불을 껐다."}]'::jsonb, '{"xp": 374, "gil": 41, "items": {"tonic": 2, "travel_ration": 1, "hf_rg_kangducheol_dummy": 1}, "title": "rg_kangducheol"}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('rg_yeoseotjjae_1', 'side', '연담·여섯째', '빚 대신 셈', '이름을 돌려준 날 셈 수첩의 숫자까지 지워져 셀 것이 없어진 채무 추적자 여섯째가 조사원을 붙든다. 조사원이 바깥에서 몇 번 싸워 이기는지 뒤따라가며 세겠다 하고, 쫓을 때 모자라는 청령단을 주문한다. 새로 적은 셈 장부 맨 위 칸에 조사원은 이름 대신 「일곱」으로 적힌다.', 'hidden_bazaar', 50, '{mdq_17}'::text[], null, 1675, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = null where quest_id = 'rg_yeoseotjjae_1';
delete from public.world_quest_steps where quest_id = 'rg_yeoseotjjae_1' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_yeoseotjjae_1', 1, '빈 칸', '빈 칸', '{"at": ["hidden_bazaar"]}'::jsonb, '[{"s": null, "t": "해가 지자 십삼문 암시장 열세 문에 하나씩 등이 올랐다. 돌바닥에 고인 물이 등불을 받아 번들거렸다. 어느 좌판에선가 마른 생선 굽는 냄새가 매캐하게 번졌다."}, {"s": null, "t": "여섯째 문 처마 밑에 검은 옷을 입은 이가 벽에 등을 대고 서 있었다. 긴 머리를 높이 묶었고, 얼굴 아래를 검은 천으로 가려 눈만 드러나 있었다. 흑련 채무 추적자 여섯째였다."}, {"s": null, "t": "여섯째는 손바닥만 한 수첩 한 권을 펴 들고 있었다. 왼손 손가락이 접혔다 펴지기를 되풀이했다. 무언가를 세는 손이었는데, 수첩은 빈 쪽이었다."}, {"s": null, "t": "내가 처마 밑으로 들어서자 여섯째가 손가락을 멈추고 눈만 들었다."}, {"s": "black_lotus:six", "t": "…손님. 등도에서 서신 건넨 뒤로 처음이다.", "fac_not": "black_lotus", "spec": 2, "grp": 1}, {"s": "black_lotus:six", "t": "…식구. 등도에서 서신 건넨 뒤로 처음이다.", "fac": "black_lotus", "spec": 1, "grp": 1}, {"s": null, "t": "나는 빈 수첩으로 무엇을 세고 있었느냐고 물었다. 여섯째가 수첩을 내 쪽으로 돌렸다. 칸마다 줄은 그어져 있는데 글자가 하나도 없었다."}, {"s": "black_lotus:six", "t": "아무것도. 셀 게 없어서 손가락만 센다. 버릇이다."}, {"s": "black_lotus:six", "t": "회원을 숫자로 적던 수첩이다. 장부에서 이름을 돌려줄 때 구슬이 숫자도 같이 지웠다. 이제 숫자는 필요 없다고. 내 칸도 지웠다."}, {"s": null, "t": "여섯째가 빈 칸 하나를 손끝으로 짚었다. 그 자리만 종이가 거칠게 일어나 있었다. 먹을 긁어낸 자리였다."}, {"s": "black_lotus:six", "t": "쫓을 빚쟁이는 아직 있다. 그건 빚 장부에 있다. 이 수첩엔 셀 게 없다."}, {"s": null, "t": "나는 그럼 무엇을 세고 싶으냐고 물었다. 여섯째가 수첩을 펴 든 채 나를 오래 보았다. 그 눈이 내 허리춤의 무기에 가서 멈췄다."}, {"s": "black_lotus:six", "t": "손님 싸움.", "fac_not": "black_lotus", "spec": 2, "grp": 2}, {"s": "black_lotus:six", "t": "식구 싸움.", "fac": "black_lotus", "spec": 1, "grp": 2}, {"s": "black_lotus:six", "t": "추적자는 쫓는 동안 센다. 몇 걸음 왔나, 몇 합 붙었나, 몇 번 이겼나. 세 둔 사람이 다음 싸움에서 산다. 그건 열 해 넘게 세서 안다."}, {"s": "black_lotus:six", "t": "등도에서 봤다. 세지 않고 싸우더라. 그러다 다친다."}, {"s": null, "t": "여섯째가 처마 밖 장터를 턱으로 가리켰다. 등 아래로 사람들이 낮은 목소리로 흥정하며 지나갔다."}, {"s": "black_lotus:six", "t": "장터 안에선 칼을 못 뽑는다. 그러니 셀 것도 없다. 바깥에서 싸워라. 따라간다. 세는 건 내가 한다."}, {"s": null, "t": "나는 어디서 싸우면 되느냐고 물었다. 여섯째가 손가락 여덟 개를 펴 보였다."}, {"s": "black_lotus:six", "t": "등도 무관 거리. 짚 목인 그림자가 칼을 배운 대로만 휘두른다. 판이 반듯해서 세기 좋다. 여덟 판."}, {"s": "black_lotus:six", "t": "그리고 청령단 둘. 쫓다 보면 사흘을 안 잔다. 그러면 영력이 먼저 바닥난다. 지어 와라. 값은 셈해서 준다."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_yeoseotjjae_1', 2, '여덟', '청령단을(를) 만든다, 무관 거리의 요괴를 물리친다, 청령단을(를) 넘긴다', '{"at": ["hidden_bazaar"], "tasks": [{"t": "craft", "items": ["clear_spirit_pill"], "n": 2}, {"t": "win", "r": ["martial_row"], "n": 8}], "give": {"clear_spirit_pill": 2}}'::jsonb, '[{"s": null, "t": "무관 거리는 부서진 과녁과 쓰러진 목인으로 가득했다. 짚 목인 그림자들이 녹슨 칼을 쉬익쉬익 휘두르며 달려들었다. 칼끝이 어깨를 스칠 때마다 짚 부스러기가 후두둑 흩날렸다."}, {"s": null, "t": "싸우는 동안 여섯째는 무너진 담 위에 쪼그려 앉아 있었다. 돕지도 끼어들지도 않았다. 내가 한 놈을 쓰러뜨릴 때마다 여섯째의 손가락이 하나씩 접혔다."}, {"s": null, "t": "십삼문으로 돌아오니 밤 장이 한창이었다. 여섯째는 처마 밑에 서자마자 수첩을 펴고 붓을 꺼냈다."}, {"s": "black_lotus:six", "t": "여덟. 여덟 다 이겼다."}, {"s": "black_lotus:six", "t": "셋째 판에서 왼발이 한 박자 늦었다. 다섯째 판에서 두 번 맞았다. 두 번 다 오른 어깨."}, {"s": null, "t": "나는 어깨를 만져 보았다. 옷이 찢겨 있었고, 손끝에 피가 조금 묻어났다. 싸우는 동안에는 몰랐던 자리였다."}, {"s": null, "t": "여섯째가 허리 주머니에서 마른 천 조각을 꺼내 내게 던져 주었다. 상처를 누르라는 손짓이었다."}, {"s": "black_lotus:six", "t": "누르고 있어라. 피는 셈에 안 넣는다."}, {"s": null, "t": "내가 놀라 여섯째를 보자, 여섯째가 수첩에 작은 점 두 개를 콕콕 찍었다."}, {"s": "black_lotus:six", "t": "맞은 쪽은 몰랐다. 나는 셌다. 그래서 세는 거다."}, {"s": "black_lotus:six", "t": "오른쪽을 맞으면 왼발이 늦는다. 다음엔 오른쪽부터 막아라. 그럼 다섯째 판은 한 번만 맞는다."}, {"s": null, "t": "나는 천으로 어깨를 누른 채, 담 위에서 어떻게 그걸 다 보았느냐고 물었다. 여섯째가 붓 끝으로 제 눈을 가리켰다."}, {"s": "black_lotus:six", "t": "눈은 발에 둔다. 칼은 발을 따라간다. 발만 보면 다 센다."}, {"s": null, "t": "여섯째는 그렇게 말하고 붓을 멈췄다. 수첩 맨 위 칸이 비어 있었다. 무엇을 적을 자리인지 여섯째도 정하지 못한 눈치였다."}, {"s": null, "t": "나는 청령단 두 알을 꺼내 내밀었다. 여섯째는 손바닥을 펴는 대신 처마 밑 걸상을 턱으로 가리켰다."}, {"s": "black_lotus:six", "t": "앉아라. 수첩부터 적는다. 다 적고 받는다. 셈이 먼저다."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_yeoseotjjae_1', 3, '일곱', '십삼문 암시장에서 쉰다, 청령단을(를) 넘긴다', '{"at": ["hidden_bazaar"], "tasks": [{"t": "rest", "r": ["hidden_bazaar"], "n": 1}], "give": {"clear_spirit_pill": 2}}'::jsonb, '[{"s": null, "t": "걸상에 앉아 있으니 장터 소리가 하나씩 귀에 들어왔다. 엽전 세는 소리가 짤랑거렸고, 뒷골목 어디선가 콜록콜록 기침 소리가 났다. 여섯째의 붓은 그 소리들 사이로 천천히 움직였다."}, {"s": null, "t": "여섯째가 다 적은 수첩을 내 무릎 위에 펴 놓았다. 「무관 거리 · 여덟 · 여덟 이김 · 셋째 왼발 · 다섯째 오른 어깨 둘」이라고 적혀 있었다. 맨 위 칸에는 「일곱」 두 글자가 있었다."}, {"s": null, "t": "나는 일곱이 무엇이냐고 물었다. 여섯째가 왼손 손등을 내 쪽으로 돌렸다. 손등에 먹 점 여섯이 줄지어 있었고, 그 가운데 하나는 지워져 흐렸다."}, {"s": "black_lotus:six", "t": "나는 여섯째. 손님은 그다음 칸. 일곱.", "fac_not": "black_lotus", "spec": 2, "grp": 1}, {"s": "black_lotus:six", "t": "나는 여섯째. 식구는 그다음 칸. 일곱.", "fac": "black_lotus", "spec": 1, "grp": 1}, {"s": "black_lotus:six", "t": "수첩엔 이름 칸이 없다. 이름을 적는 건 구슬 일이다. 나는 숫자만 적는다."}, {"s": null, "t": "그때 주판을 옆구리에 낀 구슬이 처마 앞을 지나가다 걸음을 멈췄다. 구슬이 내 무릎 위 수첩을 들여다보고 손으로 입을 가렸다."}, {"s": "black_lotus:guseul", "t": "어머, 여섯째 씨. 칸 다 지웠다고 사흘을 문간에 서 계시더니, 그새 새 장부를 차리셨네요?"}, {"s": null, "t": "여섯째가 구슬을 흘끗 보았다. 대꾸는 하지 않고 내 무릎에서 수첩을 거둬 품에 넣었다. 구슬은 주판알 하나를 탁 튕기고 웃으며 제 좌판으로 돌아갔다."}, {"s": null, "t": "여섯째가 손바닥을 펴 내 쪽으로 내밀었다. 나는 그제야 청령단 두 알을 그 손에 올려놓았다. 여섯째가 한 알씩 세어 허리 주머니에 넣고 엽전 꾸러미를 풀었다."}, {"s": "black_lotus:six", "t": "청령단 둘. 시세대로. 그리고 하나 더."}, {"s": null, "t": "여섯째가 엽전 한 닢을 더 얹어 주었다. 나는 그 한 닢은 무슨 값이냐고 물었다."}, {"s": "black_lotus:six", "t": "여덟 판 다 이긴 값. 셈에 없던 거다. 셈에 없던 건 따로 준다."}, {"s": null, "t": "여섯째가 수첩을 넣은 품을 손바닥으로 한 번 눌렀다. 엄지가 손등의 지워진 점 자리로 가서 문지르다 멈췄다."}, {"s": "black_lotus:six", "t": "…손님 싸움, 앞으로도 세도 되나. 청령단도 계속. 쫓을 땐 늘 모자라다.", "fac_not": "black_lotus", "spec": 2, "grp": 2}, {"s": "black_lotus:six", "t": "…식구 싸움, 앞으로도 세도 되나. 청령단도 계속. 쫓을 땐 늘 모자라다.", "fac": "black_lotus", "spec": 1, "grp": 2}, {"s": null, "t": "나는 그러겠다고 했다. 여섯째가 고개를 한 번 끄덕이고 손가락 하나를 접었다."}, {"s": "black_lotus:six", "t": "하나. 오늘부터 센다."}]'::jsonb, '{"gil": 205}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('rg_yeoseotjjae_2', 'side', '연담·여섯째', '하나 모자란 손가락', '그사이 넘긴 셈을 손가락으로 다시 맞추던 여섯째의 셈이 하나 어긋난다. 둘이 지맥의 뿌리에서 소리 내어 다시 세어 보니, 덩굴 뒤에 숨어 있던 매복자 하나를 여섯째가 놓쳤다. 여섯째가 손등의 지워진 점을 벌겋게 되도록 문지르고, 조사원은 묻지 않는다. 굴 어귀에서 등을 돌린 채 차를 마신다.', 'hidden_bazaar', 50, '{rg_yeoseotjjae_1}'::text[], null, 1676, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = '{"regular": "yeoseotjjae", "stage": 2}'::jsonb where quest_id = 'rg_yeoseotjjae_2';
delete from public.world_quest_steps where quest_id = 'rg_yeoseotjjae_2' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_yeoseotjjae_2', 1, '쉰둘과 쉰셋', '쉰둘과 쉰셋', '{"at": ["hidden_bazaar"]}'::jsonb, '[{"s": null, "t": "비가 그친 밤이었다. 십삼문 암시장 처마마다 빗방울이 똑똑 떨어졌고, 젖은 돌바닥에서 비릿한 흙내가 올라왔다."}, {"s": null, "t": "여섯째는 처마 밑 걸상에 앉아 수첩을 무릎에 펴 놓고 있었다. 오른손은 수첩 줄을 짚었고, 왼손은 손가락을 하나씩 접었다 폈다."}, {"s": null, "t": "내가 걸상 옆에 서자 여섯째가 눈을 들지 않은 채 입을 열었다. 셈을 끊고 싶지 않은 목소리였다."}, {"s": "black_lotus:six", "t": "그사이 넘긴 것. 청령단 열넷. 영기환 여섯. 영초 차 넷. 그건 맞다."}, {"s": "black_lotus:six", "t": "이긴 싸움. 수첩엔 쉰셋. 손가락으론 쉰둘."}, {"s": null, "t": "여섯째가 왼손을 들어 보였다. 손가락 다섯이 다 펴져 있었다. 여섯째는 그 손을 한참 내려다보다가 다시 수첩을 보았다."}, {"s": null, "t": "나는 하나쯤은 틀릴 수도 있지 않느냐고 했다. 여섯째의 고개가 천천히 들렸다."}, {"s": "black_lotus:six", "t": "안 틀린다. 열 해 넘게 하나도 안 틀렸다."}, {"s": null, "t": "여섯째의 엄지가 손등 위를 한 번 지나갔다. 지워진 점 자리에서 잠깐 머물다 떨어졌다."}, {"s": "black_lotus:six", "t": "틀린 셈은 처음부터 다시 센다. 어디서 어긋났는지 짚어야 다음에 안 어긋난다."}, {"s": null, "t": "여섯째가 수첩을 몇 장 넘겨 한 줄을 짚었다. 「지맥의 뿌리 · 다섯 · 다섯 이김」이라고 적혀 있었다."}, {"s": "black_lotus:six", "t": "여기다. 손가락은 다섯을 접었다. 그런데 그날 칼 소리는 여섯 번 났다. 소리는 기억하는데 셈이 안 맞는다."}, {"s": null, "t": "나는 그날 굴이 어두웠다고 했다. 여섯째가 수첩을 덮고 일어섰다."}, {"s": "black_lotus:six", "t": "어두운 건 까닭이 안 된다. 지맥의 뿌리에 다시 간다. 이번엔 여섯 판. 하나씩 소리 내서 센다. 그래야 귀도 같이 센다."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_yeoseotjjae_2', 2, '뿌리 속 매복자', '지맥의 뿌리의 요괴를 물리친다', '{"at": ["under_root"], "tasks": [{"t": "win", "r": ["under_root"], "n": 6}]}'::jsonb, '[{"s": null, "t": "지맥의 뿌리는 땅 밑으로 굽이굽이 파고든 굴이었다. 천장에서 굵은 뿌리가 늘어져 있었다. 뿌리 끝마다 물방울이 맺혀 똑, 똑 떨어졌고, 축축한 흙냄새가 목구멍까지 차올랐다."}, {"s": null, "t": "여섯째는 내 등 뒤 세 걸음에서 따라왔다. 내가 뿌리 지네 한 마리를 베어 넘기자 낮은 목소리가 굴 벽에 울렸다."}, {"s": "black_lotus:six", "t": "하나."}, {"s": null, "t": "둘, 셋, 넷이 차례로 이어졌다. 다섯째 놈을 쓰러뜨렸을 때, 내 왼쪽 덩굴 사이에서 무언가가 스르륵 미끄러졌다."}, {"s": null, "t": "나는 몸을 틀어 그쪽을 베었다. 덩굴 뒤에 몸을 납작 붙이고 있던 뿌리 속 매복자가 끽 비명을 지르며 털썩 쓰러졌다. 흙빛 몸뚱이가 뿌리와 똑같은 색이었다."}, {"s": "black_lotus:six", "t": "…다섯."}, {"s": null, "t": "여섯째의 목소리가 한 박자 늦게 나왔다. 여섯째는 쓰러진 매복자를 내려다보며 한동안 움직이지 않았다."}, {"s": null, "t": "굴이 조용해지자 나는 숨을 고르며 여섯째를 돌아보았다. 여섯째가 왼손 손가락 다섯을 다 접었다. 오른손 검지도 하나 더 접었다."}, {"s": "black_lotus:six", "t": "여섯. 아까 다섯째가 둘이었다. 덩굴 뒤에 하나 더. 지난번에도 저기 있었을 거다. 나는 둘을 하나로 셌다."}, {"s": "black_lotus:six", "t": "못 본 거다. 앞에 있는 것만 셌다."}, {"s": null, "t": "여섯째가 수첩을 펴려다 말고 왼손 손등을 내려다보았다. 엄지가 지워진 점 자리를 문질렀다. 한 번, 두 번, 살갗이 벌겋게 일어날 때까지 문질렀다."}, {"s": "black_lotus:six", "t": "…전에도 하나를 못 봤다. 그땐…."}, {"s": null, "t": "여섯째의 엄지가 거기서 멈췄다. 말도 거기서 끊겼다. 굴 천장에서 떨어진 물방울이 여섯째의 손등 위에서 톡 터졌다."}, {"s": null, "t": "나는 그 뒤를 묻지 않았다. 대신 굴 바닥에 주저앉아 젖은 이마를 소매로 훔쳤다. 오래 싸운 탓에 목이 바짝 타들어 갔다."}, {"s": null, "t": "여섯째가 그런 나를 보고 허리 주머니를 뒤졌다. 주머니에서는 빈 종이 꾸러미만 바스락거렸다."}, {"s": "black_lotus:six", "t": "청령단은 쫓다가 다 썼다. 차라도 끓여라. 둘. 하나씩 마신다. 셈은 마시면서 다시 맞춘다."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_yeoseotjjae_2', 3, '등 돌리고 마신 차', '영초 차을(를) 만든다, 영초 차을(를) 넘긴다', '{"at": ["under_root"], "tasks": [{"t": "craft", "items": ["spirit_tea"], "n": 2}], "give": {"spirit_tea": 2}}'::jsonb, '[{"s": null, "t": "굴 어귀 너럭바위에 앉아 차를 따르자 김이 모락모락 피어올랐다. 쌉싸름한 풀 냄새가 굴에서 불어 나오는 눅눅한 바람에 섞였다. 바위는 밤이슬에 젖어 차가웠다."}, {"s": null, "t": "여섯째가 찻잔을 받아 들고 몸을 반쯤 돌렸다. 얼굴을 가린 검은 천을 내리려면 등을 보여야 하는 모양이었다. 나도 고개를 굴 쪽으로 돌렸다."}, {"s": null, "t": "등 뒤에서 차 마시는 소리가 아주 작게 났다. 나는 잔을 내려놓는 소리가 나고 나서야 고개를 돌렸다. 검은 천은 벌써 제자리에 올라가 있었다."}, {"s": "black_lotus:six", "t": "…안 봤나."}, {"s": null, "t": "나는 굴 천장 뿌리만 세고 있었다고 했다. 여섯째의 눈가가 아주 조금 접혔다."}, {"s": "black_lotus:six", "t": "몇 개."}, {"s": null, "t": "나는 스물쯤이라고 했다. 여섯째가 고개를 저었다."}, {"s": "black_lotus:six", "t": "스물셋. 셈이 영 못쓰겠다. 그래서 내가 센다."}, {"s": null, "t": "여섯째가 수첩을 꺼내 지맥의 뿌리 줄을 찾았다. 「다섯」 위에 먹을 쭉 긋고 「여섯」이라고 고쳐 적었다. 그 옆에 작은 글씨를 덧붙였다."}, {"s": null, "t": "내가 수첩 쪽으로 고개를 기울이자, 여섯째가 숨기지 않고 그 줄을 짚어 보였다. 「하나 · 못 본 것」이라고 적혀 있었다."}, {"s": "black_lotus:six", "t": "못 본 것도 적는다. 이제부터는."}, {"s": null, "t": "여섯째가 왼손을 펴서 손등을 등잔 쪽으로 돌렸다. 아까 문지른 탓에 지워진 점 자리가 더 흐려 보였다."}, {"s": "black_lotus:six", "t": "점은 여섯이다. 하나는 지웠다. 여섯이었다가 다섯이 됐다. 그래도 나는 여섯째다."}, {"s": null, "t": "여섯째는 그 말을 하고 손을 거뒀다. 나는 그 점에 대해서도 묻지 않았다. 빈 찻잔에 차를 한 번 더 따랐을 뿐이다."}, {"s": null, "t": "여섯째가 찻잔을 받아 들고 다시 몸을 반쯤 돌렸다. 이번에는 아까보다 조금 덜 돌렸다."}]'::jsonb, '{"gil": 205}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('rg_yeoseotjjae_3', 'side', '연담·여섯째', '찾는 건 못 한다', '장날 밤, 떨어진 등을 쫓아간 좌판 집 아이가 사라진다. 「찾는 건 못 한다」던 여섯째가 조사원과 함께 연등 하수도를 뒤진다. 쥐 떼에 둘러싸인 아이는 숫자로 부르는 여섯째에게는 돌아보지 않고, 조사원이 이름을 부르자 금빛 실을 받고 고개를 든다. 여섯째의 장부에 처음으로 이름 하나가 들어간다.', 'hidden_bazaar', 50, '{rg_yeoseotjjae_2}'::text[], null, 1677, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = '{"regular": "yeoseotjjae", "stage": 3}'::jsonb where quest_id = 'rg_yeoseotjjae_3';
delete from public.world_quest_steps where quest_id = 'rg_yeoseotjjae_3' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_yeoseotjjae_3', 1, '둘째 좌판 아이', '둘째 좌판 아이', '{"at": ["hidden_bazaar"]}'::jsonb, '[{"s": null, "t": "장날이라 그날 밤 십삼문 암시장에는 사람이 들끓었다. 열세 문 사이로 흥정 소리가 웅웅 울렸다. 엿 고는 달큰한 냄새와 등 기름 타는 냄새가 뒤섞여 골목에 고였다."}, {"s": null, "t": "여섯째는 처마 밑에서 수첩을 펴던 참이었다. 여섯째가 나를 보자 손가락부터 폈다."}, {"s": "black_lotus:six", "t": "그사이. 영기환 아홉. 청령단 열하나. 이긴 싸움 백둘. 못 본 것 없음."}, {"s": null, "t": "셈이 끝나기도 전에 사람들 사이를 헤치고 아낙 하나가 달려왔다. 앞치마에 밀가루가 허옇게 묻어 있었고, 얼굴은 그보다 더 하얗게 질려 있었다."}, {"s": "q:yd_stallwife", "t": "여섯째 씨! 우리 꽃분이 못 봤수? 방금까지 좌판 밑에서 놀았는데, 고개 한 번 돌린 새에 없어졌수!"}, {"s": null, "t": "여섯째가 수첩을 탁 덮었다. 그 눈이 장터 골목을 빠르게 훑었다."}, {"s": "black_lotus:six", "t": "열셋째 문, 둘째 좌판 집 아이. 몇 살."}, {"s": "q:yd_stallwife", "t": "일곱 살이우. 장터 등이라면 사족을 못 써서, 바람에 떨어진 등만 보면 쫓아가는데… 아이고, 어쩌면 좋수…."}, {"s": null, "t": "아낙의 목소리가 떨리다 끝내 뚝 끊겼다. 여섯째의 엄지가 손등의 지워진 점 자리로 갔다가 그대로 굳었다."}, {"s": null, "t": "여섯째가 나를 보았다. 무언가를 부탁하는 눈이었다."}, {"s": "black_lotus:six", "t": "…찾아 줘라. 나는 셀 줄만 안다. 찾는 건 못 한다."}, {"s": null, "t": "나는 같이 찾자고 했다. 여섯째는 잠깐 망설이다가 수첩을 품에 넣었다."}, {"s": "black_lotus:six", "t": "떨어진 등을 쫓아갔으면 아래다. 연등 하수도. 장터 등 찌꺼기가 다 그리로 흘러간다."}, {"s": "black_lotus:six", "t": "하수도는 굽이가 많다. 하나씩 뒤진다. 셋쯤 뒤지면 나온다. 그 안에 찾아야 한다. 쥐 떼가 먼저 찾기 전에."}, {"s": null, "t": "아낙이 앞치마를 움켜쥐고 주저앉았다. 여섯째가 아낙 앞에 한쪽 무릎을 꿇고 짧게 말했다."}, {"s": "black_lotus:six", "t": "여기 있어라. 둘째 좌판 등 켜 두고. 아이가 보고 돌아오게."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_yeoseotjjae_3', 2, '숫자로는 안 돌아본다', '연등 하수도을(를) 살핀다', '{"at": ["lotus_sewer"], "tasks": [{"t": "search", "r": ["lotus_sewer"], "n": 3}]}'::jsonb, '[{"s": null, "t": "연등 하수도 물길에는 장터에서 흘러내린 깨진 등 조각이 둥둥 떠 있었다. 물비린내와 썩은 기름 냄새가 코를 찔렀다. 발을 디딜 때마다 미끄러운 이끼가 질척거렸다."}, {"s": null, "t": "셋째 굽이를 돌았을 때 물길 건너 돌턱 위에 작은 그림자가 웅크리고 있었다. 아이 하나가 찢어진 등을 품에 꼭 안고 있었다. 그 둘레로 하수 쥐 떼가 찍찍거리며 몰려들고 있었다."}, {"s": null, "t": "내 등 뒤에서 여섯째가 숨을 훅 들이켰다."}, {"s": "black_lotus:six", "t": "찾았다…!"}, {"s": null, "t": "여섯째가 돌턱 쪽으로 한 걸음 내디디며 목소리를 높였다. 여섯째가 소리치는 것을 나는 처음 들었다."}, {"s": "black_lotus:six", "t": "열셋째 문, 둘째 좌판! 그 자리에 있어라! 움직이지 마라!"}, {"s": null, "t": "아이는 돌아보지 않았다. 등을 더 꼭 끌어안고 쥐 떼만 쳐다보며 바들바들 떨었다."}, {"s": "black_lotus:six", "t": "둘째 좌판! 들리나!"}, {"s": null, "t": "아이의 어깨가 움찔했지만 고개는 들리지 않았다. 여섯째가 입을 다물고 나를 돌아보았다. 손등을 문지르던 엄지가 덜덜 떨리고 있었다."}, {"s": "black_lotus:six", "t": "…안 돌아본다. 숫자로는."}, {"s": null, "t": "나는 장터에서 아낙이 부르던 이름을 떠올렸다. 물길 건너로 그 이름을 꽃분아, 하고 불렀다."}, {"s": null, "t": "내 입에서 나간 하얀 입김이 흩어지지 않았다. 입김은 가느다란 금빛 실로 엉기더니 어두운 물 위를 스르르 건너갔다. 실이 지나가는 자리마다 검은 물살이 금빛으로 반짝였다."}, {"s": null, "t": "실이 가슴께에 닿자 아이가 고개를 번쩍 들었다. 눈물로 범벅이 된 얼굴이 금빛을 받아 환해졌다. 아이는 제 가슴을 손으로 꾹 눌렀다."}, {"s": "q:md_child", "t": "…엄마가 부르는 거랑 똑같아. 여기가 따뜻해."}, {"s": null, "t": "아이가 일어서려다 쥐 떼 앞에서 다시 주저앉았다. 쥐들이 누런 이빨을 드러내며 찍찍 울어 댔다."}, {"s": null, "t": "여섯째가 허리에서 짧은 칼을 뽑았다. 칼을 쥔 채 아이 쪽을 보며 입을 열었다. 낮고 서툰 목소리였다."}, {"s": "black_lotus:six", "t": "꽃분이. …꽃분이, 거기 있어라. 쥐는 우리가 센다."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_yeoseotjjae_3', 3, '장부에 든 이름', '연등 하수도의 요괴를 물리친다', '{"at": ["hidden_bazaar"], "tasks": [{"t": "win", "r": ["lotus_sewer"], "n": 5}]}'::jsonb, '[{"s": null, "t": "쥐 떼를 쫓아내자 여섯째가 물길을 첨벙첨벙 건너가 아이를 안아 올렸다. 아이는 여섯째의 목에 팔을 감고도 찢어진 등을 놓지 않았다. 나는 등잔을 들고 앞서 걸으며 미끄러운 돌을 하나씩 비췄다."}, {"s": null, "t": "장터로 올라가는 사다리 앞에서 여섯째가 아이를 등에 업었다. 나는 사다리 아래에서 아이의 발이 미끄러지지 않게 신발 밑을 받쳐 주었다."}, {"s": null, "t": "열셋째 문 둘째 좌판에는 여섯째 말대로 등이 켜져 있었다. 아낙이 아이를 보자마자 맨발로 뛰어나와 와락 끌어안았다."}, {"s": "q:yd_stallwife", "t": "꽃분아, 이 녀석아! 어딜 갔었어, 어딜! …여섯째 씨, 고맙수. 어떻게 찾았수?"}, {"s": null, "t": "여섯째가 젖은 소매를 털며 턱으로 나를 가리켰다."}, {"s": "black_lotus:six", "t": "찾은 건 저쪽이다. 나는 쥐를 셌다. 다섯."}, {"s": null, "t": "아이가 엄마 품에서 고개만 빼고 여섯째를 올려다보았다."}, {"s": "q:md_child", "t": "검은 천 쓴 사람은 숫자로만 불렀어요. 그래서 나 부르는 줄 몰랐어요."}, {"s": null, "t": "아낙이 허둥지둥 아이 입을 막았다. 여섯째는 아무 말도 하지 않고 아이 앞에 쪼그려 앉아 눈높이를 맞췄다."}, {"s": "black_lotus:six", "t": "…꽃분이. 맞나."}, {"s": "q:md_child", "t": "응. 꽃분이."}, {"s": "black_lotus:six", "t": "꽃분이. 다음엔 등 쫓아가지 마라. 떨어진 등은 내가 주워 온다."}, {"s": null, "t": "아이가 고개를 끄덕이며 찢어진 등을 여섯째에게 내밀었다. 여섯째는 그 등을 두 손으로 받아 한참 들여다보았다."}, {"s": null, "t": "여섯째 문 처마 밑으로 돌아오자 여섯째가 수첩을 폈다. 「연등 하수도 · 쥐 다섯 · 다섯 이김」 아래에 서툰 글씨로 「꽃분이」라고 적었다. 수첩에 처음 들어간 이름이었다."}, {"s": null, "t": "나는 숫자 말고 이름을 적었다고 했다. 여섯째가 붓을 멈췄다."}, {"s": "black_lotus:six", "t": "아이는 숫자가 없다. 그래서 이름을 적었다."}, {"s": "black_lotus:six", "t": "숫자로 부르면 안 돌아본다. 오늘 셌다. …손님이 부를 땐 돌아봤다.", "fac_not": "black_lotus", "spec": 2, "grp": 1}, {"s": "black_lotus:six", "t": "숫자로 부르면 안 돌아본다. 오늘 셌다. …식구가 부를 땐 돌아봤다.", "fac": "black_lotus", "spec": 1, "grp": 1}, {"s": null, "t": "여섯째가 맨 위 칸의 「일곱」을 손끝으로 짚었다가 떼었다. 그 칸은 고치지 않았다. 찢어진 등은 처마 못에 조심스럽게 걸어 두었다."}]'::jsonb, '{"gil": 205}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('rg_yeoseotjjae_4', 'side', '연담·여섯째', '입에 안 붙은 이름', '흑련 장부고 지붕에 금줄귀가 들어앉아 기와가 들린다. 둘이 사다리를 함께 메고 올라가 금줄귀를 쫓고, 미끄러진 조사원을 여섯째가 붙잡는다. 용마루에 나란히 앉아 장터 등이 꺼지는 것을 세던 밤, 여섯째가 돌려받은 이름이 아직 입에 안 붙었다고 털어놓는다. 이름은 말하지 않고, 조사원도 묻지 않는다.', 'hidden_bazaar', 50, '{rg_yeoseotjjae_3}'::text[], null, 1678, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
